// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":77,"question":"يقول: إنَّ الإسلام والإيمان ليسا محصورين برسالة سيدنا محمدٍ عليه الصلاة والسلام فقط، بل إنَّ الإسلام والإيمان يخصَّان كلَّ إنسانٍ يعبد الله بأي صورةٍ كانت، قبل وبعد البعثة المحمدية المباركة؟","title":"حكم من بلغته رسالة الإسلام ولم يدخل فيه","answer":"الجواب: أما قبل بعث محمدٍ ﷺ: فكل مَن آمن بالرسل الماضين فهو من أهل الجنة: مَن آمن بموسى، بعيسى، بهود، بصالح، بجميع الرسل، فهو من أهل الجنة إذا مات على ذلك.\nأمَّا بعد محمدٍ ﷺ: فليس من أهل الجنة إلا مَن تابع محمدًا صلى الله عليه وسلم، فجميع أهل الأرض بعد بعث محمدٍ ﷺ ليس لهم نجاةٌ إلَّا باتباع محمدٍ عليه الصلاة والسلام، قال النبيُّ ﷺ: كل أمَّتي يدخلون الجنة إلَّا مَن أبى، قيل: يا رسول الله، مَن يأبى؟ قال: مَن أطاعني دخل الجنَّةَ، ومَن عصاني دخل النار، فأتباع محمدٍ ﷺ هم الذين يدخلون الجنة دون غيرهم، ويقول ﷺ: والذي نفسي بيده، لا يسمع بي أحدٌ من هذه الأمة: يهودي ولا نصراني، ثم يموت ولم يُؤمن بالذي أُرْسِلْتُ به إلَّا كان من أهل النار.\nفلا يكون من أهل الجنة بعد بعث محمدٍ ﷺ إلَّا مَن تابعه، هذا هو الذي يكون من أهل الجنَّة، أما مَن بلغه خبرُه وكفر به ولم يُؤمن فهو من أهل النار.\nأما مَن لم يبلغه خبرُ النبي ﷺ من أهل الفترات، الذين لم يسمعوا بالرسول ولا بالقرآن، فهؤلاء يُقال لهم: أهل الفترة، وهؤلاء أمرهم إلى الله يوم القيامة، يمتحنهم جلَّ وعلا، فمَن نجح في الامتحان دخل الجنة، ومَن لم ينجح دخل النار -نسأل الله السلامة.\nوأما مَن بلغته رسالتُه ﷺ، وبلغه القرآن، ولم يؤمن به، فهو من أهل النار -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/3045/حكم-من-بلغته-رسالة-الاسلام-ولم-يدخل-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0054.mp3","categories":["الجنايات والحدود","ضوابط التكفير"]},{"id":348,"question":"هل يعذر الإنسان بجهله لأصول الاعتقاد؟","title":"هل يعذر الإنسان بجهله لأصول الاعتقاد؟","answer":"الجواب: ليس هذا محلّ عذرٍ، أصول الدين محلّ إجماعٍ، ليس محل عذرٍ بالجهل إذا كان بين المسلمين، الله قال: وَأُوحِيَ إِلَيَّ هَذَا الْقُرْآنُ لِأُنْذِرَكُمْ بِهِ وَمَنْ بَلَغَ [الأنعام:19]، وقال: هَذَا بَلَاغٌ لِلنَّاسِ [إبراهيم:52].\nفإذا بلغه القرآن، وبلغته السنة، وهو بين المسلمين؛ ما هو معذورٌ بالجهل إذا وقع في الشرك والإلحاد والشيوعية أو الوثنية أو سبّ الدين، ليس بمعذورٍ، يقول الرسول ﷺ في الحديث الصَّحيح الذي رواه مسلم: والذي نفسي بيده لا يسمع بي أحدٌ من هذه الأمة: يهودي ولا نصراني، ثم يموت ولم يؤمن بالذي أُرسلتُ به إلا كان من أهل النار، قال: لا يسمع، وما قال: \"ما يفهم\"، فإذا سمع الخبر وبلغه خبر رسول الله ﷺ وبلغه القرآن؛ كفى، إلا إذا كان في بلادٍ بعيدةٍ ما يعلم ولا يدري، ولا بلغه القرآن، ولا بلغته السنة، فهذا حكمه حكم أهل الفترة، والصحيح فيهم أنهم يُمتحنون يوم القيامة، ويُؤمرون وينهون، فإن أطاعوا نجوا، وإن عصوا هلكوا، كما قال تعالى: وَمَا كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولًا [الإسراء:15].","link":"https://binbaz.org.sa/fatwas/4437/هل-يعذر-الانسان-بجهله-لاصول-الاعتقاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0401.mp3","categories":["الجنايات والحدود","ضوابط التكفير"]},{"id":766,"question":"هل يُعذر المسلم إذا فعل شيئًا من الشرك -كالذبح والتَّسول- جاهلًا؟","title":"هل يُعذر من يفعل شيئا من الشرك جهلاً؟","answer":"الجواب: الأمور قسمان: قسم يُعذر فيه بالجهل، وقسمٌ لا يُعذر فيه بالجهل: فإذا كان بين المسلمين وأتى الشرك بالله وعبد غير الله ما يُعذر؛ لأنه مقصرٌ، لم يسأل، ولم يتبصر، ولم يسأل عن دينه، فيكون غير معذورٍ، فالذي يعبد غير الله: من أمواتٍ، أو أشجارٍ، أو أحجارٍ، أو أصنامٍ، هذا غير معذورٍ بين المسلمين؛ لأنَّ هذا أصل الدين، وأساس الملة، والنبي ﷺ لما استأذن ربَّه أن يستغفر لأمِّه -وهي ماتت في الجاهلية- لم يُؤذن له أن يستغفر لها، هي ماتت في الجاهلية، وقال: إنَّ أبي وأباك في النار؛ لأنه مات على الشرك بالله، وعلى عبادة غيره، وهي ماتت على ذلك، على دين قومها، فكيف بالذي بين المسلمين يعبد البدوي، ويعبد الحسين، أو يعبد الشيخ عبدالقادر الجيلاني، أو يعبد الرسول محمدًا ﷺ، أو يعبد ابن عباس، أو يعبد عمر، أو عليًّا، أو الحسن، أو الحسين -كما تعبدهم الرافضة- أو غير ذلك؟! هؤلاء لا يُعذرون؛ لأنهم أتوا بالشرك الأكبر، هم في الدنيا حكمُهم حكم الكفرة، وأمرهم إلى الله في الآخرة.\nوهناك أمورٌ قد يجهلها الإنسانُ في فروع المسائل التي قد تلتبس عليه، أو كونه في بلادٍ بعيدةٍ عن الإسلام، في أطراف الدنيا، بعيدة عن الإسلام، هذا قد يُعذر، ويكون حكمه حكم أهل الفترة، أمره إلى الله يوم القيامة، ويُمتحن يوم القيامة، ويُؤمر فإن أجاب دخل الجنة، وإن عصى دخل النار.","link":"https://binbaz.org.sa/fatwas/20703/هل-يعذر-من-يفعل-شيىا-من-الشرك-جهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0599هل يعذر المسلم إذا فعل شيئاً من الشرك كالذبح والتوسل جاهلاً ؟ ابن باز فتاوى المحاضرات.mp3","categories":["ضوابط التكفير"]},{"id":977,"question":"يقول: حيث إنَّ كثيرًا من الناس يقعون في الشرك من غير قصدٍ، فما حكم ذلك؟","title":"حكم من يقع في شيء من الشرك دون قصد","answer":"الجواب: الواجب تنبيه مَن وقع في الشرك، تنبيهه على خطورة ما وقع فيه، وأنه وقع في أمرٍ عظيمٍ، فيُنبّه على خطورة ذلك، ويُؤمر بالتوبة؛ لأنَّ أمور الشرك لا يُعذر فيها بالجهالة، وهو بين المسلمين يجب عليه أن يتعلَّم ويسأل، ولا يتساهل.\nفالذي يدعو غير الله، ويستغيث بغير الله، أو يدعو الجنَّ، ويستغيث بهم، أو يستنصر بهم؛ قد أتى كفرًا عظيمًا، لا بدّ أن يُنَبَّه، وإذا قال: يا جن خذوه، أو: يا سبعة خذوه، أو: يا جن المحلّ الفلاني خذوا فلانًا، أو افعلوا به كذا، أو انصرونا على كذا، أو ساعدونا في كذا؛ فهذا مثل الذي يقول: يا عُزَّى، ويا مناة، انصرونا، أو يدعو الأموات والغائبين، كلهم سواء، كالذي يقول: يا سيدي البدوي، أو: يا سيدي الحسين، أو: يا ست زينب، أو: يا فلان، أو: يا فلانة، انصرونا، أو أغيثونا؛ هذا كفرٌ أكبر، شركٌ أكبر، أو: يا شيخ عبدالقادر الجيلاني، انصرنا، أو: يا فلان، من الأموات، أو: يا رسول الله، انصرنا، بعد وفاته صلى الله عليه وسلم، أو: يا أبا بكر، أو: يا عمر، أو: يا عثمان، انصرونا؛ هذا شركٌ أكبر؛ لأن الله يقول: فَلَا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، ويقول: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لَا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لَا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] سمَّاهم كفرة بذلك، وقال جلَّ وعلا: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ  ۝  إِنْ تَدْعُوهُمْ لَا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:13- 14]، فسمَّى دُعاءهم: شركًا، والمشركون يدعون غير الله، ويستغيثون بغير الله، ويرون أنَّ ذلك قربة لله، وأنهم يتوسَّلون بهذا الشرك، قال تعالى: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لَا يَضُرُّهُمْ وَلَا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلَاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ فردَّ الله عليهم بقوله: قُلْ أَتُنَبِّئُونَ اللَّهَ بِمَا لَا يَعْلَمُ فِي السَّمَاوَاتِ وَلَا فِي الْأَرْضِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ [يونس:18] سمَّاه: شركًا، عملًا، قال تعالى في سورة التنزيل: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ  ۝  أَلَا لِلَّهِ الدِّينُ الْخَالِصُ وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى يعني: يقولون: ما نعبدهم إلا ليُقربونا إلى الله زلفى، فردَّ الله عليهم بقوله: إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لَا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ [الزمر:2- 3]، فبين  أنَّ الكفرة كفرة في ذلك.\nفهذا يدل على أنَّ دعاء غير الله كفرٌ وضلالٌ؛ لأنهم قالوا: مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى، فبين  أنَّ هذا باطلٌ فقال: إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لَا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ، فسمَّاهم: كذبة، بزعمهم أنَّ هؤلاء المدعوين يُقربونهم زلفى، وسماهم: كفرة، بدُعائهم إيَّاهم، وتشفّعهم بهم، واستنصارهم بهم.\nفهذا يُبين لنا أنَّ دعوة الأصنام من دون الله والأموات كفرٌ وضلالٌ، وأن قولهم: \"أنها تُقربهم إلى الله\" كذبٌ لا صحةَ له، فليسوا يُقربونهم، وليس ذلك جائزًا في حقِّهم، بل هم أحقّ، بل هو من الكفر بالله .","link":"https://binbaz.org.sa/fatwas/21033/حكم-من-يقع-في-شيء-من-الشرك-دون-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0830حيث كثير من الناس يقعون في الشرك من غير قصد فما حكم ذلك؟ابن باز فتاوى المحاضرات.mp3","categories":["ضوابط التكفير"]},{"id":1055,"question":"هل يُعتبر الخطأ في العقيدة داخلًا تحت قوله تعالى: رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286]؟","title":"هل يُعذر المسلم بالجهل في خطأ العقيدة؟","answer":"الجواب:\nالعقيدة تجب فيها العناية؛ لأنها أوضح الواضحات، وأهم المهمات، فالواجب فيها العناية والتَّبصر والتَّفقه، ولا يُعذر فيها بدعوى الجهالة والخطأ. لكن إذا علم الله منه الصدقَ، واجتهد في الحقِّ، وطلب الحقَّ، ثم أخطأ وتدارك؛ فلا يضرُّه، فإن الخطأ داؤه التَّدارك والتَّوبة. أو كان ممن لم تبلغه الدَّعوةُ، فهذا يُكلَّف يوم القيامة ويُمْتَحَنُ، فإن أجاب دخل الجنةَ، وإن عصى دخل النار. أما الذي بين المسلمين فلا يُعذر بالعقيدة، ولا يُعذر بالإعراض والغفلة، بل يتفقَّه ويتعلم ويسأل، العقيدة هي توحيد الله والإخلاص، وهو الإيمان به ورسله، فإذا أشرك بالله وهو بين المسلمين لا يُعذر بهذا، لا بدّ من التَّبصر والتَّعلم والسؤال.","link":"https://binbaz.org.sa/fatwas/21075/هل-يعذر-المسلم-بالجهل-في-خطا-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0871هل يعتبر الخطأ في العقيدة داخل في قوله تعالى ربنا لا تؤخذنا أن نسينا أو أخطأنا؟ ابن باز.mp3","categories":["ضوابط التكفير"]},{"id":1347,"question":"قول عمر للرسول ﷺ عندما قال لحاطب: دعني أضرب عنق هذا المنافق، كلام ابن القيم، يقول إن الإنسان لو قال لأخيه \"يا كافر\" غَضَبًا لله وحُرقة على الدين أنه لا يُؤاخذ بهذا الكلام؟","title":"حكم مَن قال لأخيه \"يا كافر\" غَضَبًا لله","answer":"الجواب:\nمُحْتَمِل، والواجب التَّوَقِّي؛ لأن الرسول ﷺ قال: من قال لأخيه يا كافر أو يا عدو الله وليس كذلك إلا حَارَ عليه. خَطَر؛ فالإنسان يَتَوَقَّاه، ولا يَعْجَل في الأمور. ومَنْ أظْهَر النفاق وأظهر الكفر؛ وُصف بذلك.","link":"https://binbaz.org.sa/fatwas/21438/حكم-من-قال-لاخيه-يا-كافر-غضبا-لله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من قال لأخيه يا كافر غضبا لله.mp3","categories":["ضوابط التكفير"]},{"id":1450,"question":"س: ............","title":"مسألة في التكفير","answer":"إذا قام عليه الدليل يكفر، أما إذا كان في بلدٍ ما بلغه فيها الدليل فهذا أمره إلى الله، يصير من أصحاب الفترة، لكن إذا بلغه القرآن والسنة فهذا يُبَيَّن له الحكم، فإن أصرَّ كفر.\nس: إذا لم تبلغه الحُجَّة؟\nج: إذا بلغه القرآن والسنة فقد بلغته الحجة.","link":"https://binbaz.org.sa/fatwas/21547/مسالة-في-التكفير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في التكفير.mp3","categories":["ضوابط التكفير"]},{"id":2140,"question":"يقول سائلٌ: هل يجوز لعن الكافر المُعَيَّن؟ وهل هناك فرقٌ بين الحي والميت؟","title":"هل يجوز لعن الكافر المُعَيَّن؟","answer":"الجواب:\nلاـ يلعنه على العموم، يلعن اليهودَ والنَّصارى والكفَّار على العموم، إلا الكافر الذي يُؤذي المسلمين؛ فإنه إذا رأى وليُّ الأمر لعنه فلا بأس، إذا كان يُؤذيهم بالقتال أو بالمُضايقات، مثلما لعن النبيُّ ﷺ جماعةً من أهل مكة: كأبي جهلٍ، وعتبة بن ربيعة، لما آذوا المسلمين.","link":"https://binbaz.org.sa/fatwas/22258/هل-يجوز-لعن-الكافر-المعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم لعن الكافر المعين الحي أو الميت.mp3","categories":["ضوابط التكفير"]},{"id":3408,"question":"في السودان انتشرت الصوفية، واعتقد الناس العقائد الباطلة، مع قبائلهم، لكن يقول بعض الإخوان أنهم معذورون بجهلهم؟","title":"هل يُعذر بالجهل مَنْ يعتقد العقائد الشركية؟","answer":"الجواب: لا، ما هم معذورون القرآن موجود، والسنة موجودة بين المسلمين، يجب أن يتعلموا، من أتى الشرك فهو كافر، إلا إذا كان في بلاد ما بلغته الدعوة، أن يكون في بلاد الغفلة، يكون حينئذ من أهل الفترة، أمره إلى الله يوم القيامة. أما مَنْ بين المسلمين يَعْبُد القبور، ويَعْبُد الأموات؛ فهذا مشرك، لا بدّ يتعلم، ويسأل، وإلا فهو مشرك مثال عُبّاد البدوي، وعُبّاد الحسين، وعُبّاد عبدالقادر الجيلاني، وأشباههم، نسأل الله العافية.\nس: هل تعلم بلدًا يا شيخ ما بلغهم شيء؟\nالشيخ: ما نعلم شيئًا، لكن لو وُجد بلاد ما بلغهم؛ يكونوا من أهل الفترة.","link":"https://binbaz.org.sa/fatwas/23580/هل-يعذر-بالجهل-من-يعتقد-العقاىد-الشركية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعذر بالجهل من يعتقد العقائد الباطلة.mp3","categories":["ضوابط التكفير"]},{"id":3797,"question":"بالنسبة للعوام من طوائف الشيعة، هل يعذروا بجهلهم...؟","title":"هل يُعذر عوامُ الشيعة بجهلهم؟","answer":"الجواب: قد يعذرون من جهة عدم التكفير إلا بعد البيان، لكن ما يعذرون في اتباع الباطل، يُعلّمون ويُوجّهون، ويستحقون الهجر؛ حتى يرجعوا عمَّا هم فيه من الباطل.  أما التكفير، قد يعذرون من جهة التكفير حتى يُبيّن لهم... الرافضة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/23996/هل-يعذر-عوام-الشيعة-بجهلهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم عوام الشيعة.mp3","categories":["ضوابط التكفير"]},{"id":4205,"question":"الجهال الذين أشركوا وهم في بلاد الإسلام.. حول القبور... ما يعرفون.. لُبّس عليهم..؟","title":"هل يعذر الجاهل إذا وقع في الشرك؟","answer":"الجواب: ولو ما دام بين المسلمين وبلغه القرآن لا يكون من أهل الفترة، ولا يكون من أهل العذر، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24466/هل-يعذر-الجاهل-اذا-وقع-في-الشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعذر الجاهل إذا وقع في الشرك.mp3","categories":["ضوابط التكفير"]},{"id":4315,"question":"إذا استغاث بقبر أحد الصالحين وهو جاهل هل يكفر؟","title":"حكم من استغاث بقبر أحد الصالحين جاهلًا","answer":"الجواب: نعم شرك أكبر، نسأل الله العافية، هذه من الأمور التي ما تخفى بين المسلمين.\nس: إذا كان جاهلًا يكفر؟\nج: ولو، هذا من الكفر الأكبر ولا يُعذر بقوله: إني جاهل، هذا أمر معلوم من الدين بالضرورة، لكن إذا كان صادقًا يبادر بالتوبة.\nس: في بعض البلدان يطوفون؟\nج: نعم في الشام وفي مصر وفي غيرها.\nس: طيب يكفرون؟\nج: نعم، نعم الرسول ﷺ كفرهم، والمسلمون قاتلوهم، قاتلوا الوثنيين وفيهم العامة الذين ما يعرفون شيئًا تبع ساداتهم.\nس: والذبح؟\nج: الذبح لغير الله شرك: قُلْ إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ  ۝  لَا شَرِيكَ لَهُ [الأنعام:162-163]\nس: خاصة في دول؟\nج: العامة تبع القادة نعم، تبع الكفار، تبع اليهود والنصارى وأشباههم، قادتهم تبع لهم، نسأل الله العافية، عامتهم تبع لهم.","link":"https://binbaz.org.sa/fatwas/24589/حكم-من-استغاث-بقبر-احد-الصالحين-جاهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يكفر من استغاث بقبر أحد الصالحين جاهلًا.mp3","categories":["ضوابط التكفير"]},{"id":4738,"question":"القول الراجح في أصحاب الفترة ومَن لم تبلغه الدَّعوة ومَن مات من أبناء المشركين؟","title":"ما الراجح في أصحاب الفترة ومَن لم تبلغه الدَّعوة؟","answer":"القول الراجح أنهم تُقام عليهم الحجَّة يوم القيامة، كما ذكره ابنُ القيم رحمه الله، وذكره ابنُ كثير عند قوله: وَمَا كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولًا [الإسراء:15] وغيرهم.","link":"https://binbaz.org.sa/fatwas/25064/ما-الراجح-في-اصحاب-الفترة-ومن-لم-تبلغه-الدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/القول الراجح في أصحاب الفترة ومَن لم تبلغه الدَّعوة.mp3","categories":["ضوابط التكفير"]},{"id":4748,"question":"ما يلزم الجاهل القبوري؟","title":"ما حكم القبوري الجاهل؟","answer":"هذه من الأمور العظيمة التي جاء بها الإسلام وجاءت بها الرسل، لا يخفى مثلها، والقرآن بين أيديهم، والسنة بين أيديهم، والعلماء بين أيديهم، ولكنَّهم قانعون بما هم عليه، لا يرضون أن يُنَبَّهوا، نسأل الله العافية.\nثم لو قُدِّر أنهم جهلوا، فالحكم في الدنيا على هذا، مثل سائر الكفار، أما الآخرة: إذا كان الله جلَّ وعلا يعلم من قلوبهم أنهم جهلوا وأنهم يطلبون الحقَّ، يكون لهم حكمُ الآخرة عند الله، الله يتولى حسابهم، كأهل الفترات، قد يُمتحنون يوم القيامة، نسأل الله العافية، وقد بيَّن سبحانه أنَّ أكثرهم لا يعقل ولا يفهم، قال تعالى: إِنَّهُمُ اتَّخَذُوا الشَّيَاطِينَ أَوْلِيَاءَ مِنْ دُونِ اللَّهِ وَيَحْسَبُونَ أَنَّهُمْ مُهْتَدُونَ [الأعراف:30]، وقال تعالى: قُلْ هَلْ نُنَبِّئُكُمْ بِالْأَخْسَرِينَ أَعْمَالًا  ۝  الَّذِينَ ضَلَّ سَعْيُهُمْ فِي الْحَيَاةِ الدُّنْيَا وَهُمْ يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعًا [الكهف:103- 104]، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/25087/ما-حكم-القبوري-الجاهل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم القبوري الجاهل.mp3","categories":["ضوابط التكفير"]},{"id":5081,"question":"مَن لم يُكفِّر اليهود والنَّصارى؟","title":"ما حكم مَن لم يُكفِّر اليهود والنَّصارى؟","answer":"الجواب: هو مثلهم، مَن لم يكفر الكفَّار فهو مثلهم، لا بد من الإيمان بالله وتكفير مَن كفر به؛ ولهذا يقول النبيُّ ﷺ في الحديث الصَّحيح: مَن وحَّد الله وكفر بما يُعبد من دون الله؛ حَرُم ماله ودمه، وحسابه على الله، ويقول الله جلَّ وعلا: فَمَنْ يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِنْ بِاللَّهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَى لَا انْفِصَامَ لَهَا وَاللَّهُ سَمِيعٌ عَلِيمٌ [البقرة:256].  فلا بد من الإيمان بالله، وتوحيده، والإخلاص له، والإيمان بإيمان المؤمنين، ولا بد من تكفير الكافرين الذين بلغتهم الشريعةُ ولم يُؤمنوا: كاليهود، والنَّصارى، والمجوس، والشُّيوعيين، وغيرهم ممن يُوجد اليوم وقبل اليوم وبلغتهم رسالةُ الله ولم يُؤمنوا؛ فهم من أهل النار؛ كفَّارٌ.","link":"https://binbaz.org.sa/fatwas/29422/ما-حكم من-لم-يكفر-اليهود-والنصارى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم مَن لم يُكفِّر اليهود والنَّصارى؟.mp3","categories":["ضوابط التكفير"]},{"id":5498,"question":"كثير من الناس المنتسبين إلى السَّلفية يشترطون في إقامة الحُجَّة أن يكون من العلماء، فإذا وقع العامي على كلام كفرٍ يقول له: لا، ما تكفّر؟","title":"هل يجوز للعامي أن يُكَفّر أحدًا؟","answer":"الجواب: إقامة الدليل هذه إقامة الحُجَّة، كل على حسب حاله. س: لكن يجب على العامي أن يُكفِّر مَن قام فيه الكفر؟ ج: إذا ثبت عليه الكفر كفر، وأيش المانع؟ إذا ثبت عنده ما يُوجب كفره كفَّره، مثل: مَن كفر أبي جهل وأبي طالب وعتبة بن ربيعة وشيبة بن ربيعة، الدليل أنهم ماتوا على الكفر، قتلهم النبيُّ يوم بدر كفارًا. س: يُمنع العامي من التَّكفير؟ ج: العامي لا يُكفّر إلا بالدليل، العامي ما عنده علم، مسكين، لكن إذا كان عنده علم بشيءٍ معينٍ مثل: مَن جحد تحريم الزنا، فهذا يكفر عند العامَّة والخاصَّة، ما فيه شبهة، لو قال واحد: الزنا حلال، كفر عند الجميع؛ عند العامة وغيرهم، هذه ما يحتاج لها أدلة، أو قال: إنَّ الشرك جائز، يجوز للناس أن يعبدوا غير الله، أحد يشك في هذا؟ ما يحتاج أدلةً، لو قال: يجوز للناس أن يعبدوا الأصنام، وأن يعبدوا النجوم، وأن يعبدوا الجنَّ؛ كفر. التوقف في الأشياء المُشْكلة التي قد تخفى على العامي، أو يقول إنسان: ترى الصلاة ما هي بواجبة، مَن شاء صلَّى، ومَن شاء لا يُصلي.[1]","link":"https://binbaz.org.sa/fatwas/31408/هل-يجوز-للعامي-ان-يكفر-احدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 012.mp3","categories":["ضوابط التكفير"]},{"id":5519,"question":"يذكر العلماء في أهل البادية أنَّ الأعرابي قد يُعذر، فما هي المسائل التي قد يُعذر فيها صاحبُ البادية؟ وهل هذا خاصّ بزمن النبي ﷺ عند بداية الإسلام؟","title":"ما الأمور التي قد يُعذر فيها صاحبُ البادية؟","answer":"الجواب: يُعذر الأعرابي وغير الأعرابي بالشيء الذي يمكن جهله، مثل: بعض أركان الصلاة، بعض أركان الزكاة، بعض المفطرات. أما: جَحَد الصلاة رأسًا وقال: لا أُصلي، أو جحد الصيام رأسًا وقال: لا أصوم رمضان، لا يُعذر؛ لأنَّ هذا شيء معلوم من الدِّين بالضَّرورة، كل مسلمٍ يعرف هذا. أو جحد شروط الحج، أو أنَّ عرفة من واجبات الحج ومن أعمال الحج؛ لأنه قد يخفى عليه، لكن يُقرّ بالحج، وأنه فرض؛ لأنَّ مثل هذه قد تخفى على العامي. س: يُذكر عن بعضهم أنه ما يعرف الجَنَابة، وأنه ما يغتسل منها؟ ج: يُعَلَّم، العامِّي قد لا يفهم، وخصوصًا بعض النساء، ولا يَكْفُر.[1]","link":"https://binbaz.org.sa/fatwas/31452/ما-الامور-التي-قد-يعذر-فيها-صاحب-البادية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 034.mp3","categories":["ضوابط التكفير"]},{"id":5521,"question":"مَن وصلته كتب مُنحرفة ليس فيها عقيدة ولا توحيد، هل يُعذر بالجهل؟","title":"هل يُعذر بالجهل مَنْ نشأ على عقيدة منحرفة؟","answer":"الجواب: إذا كان بين المسلمين ما يُعذر بالشرك، أما الذي قد يخفى مثل: بعض واجبات الحج، أو واجبات العمرة، أو واجبات الصيام، أو الزكاة، وبعض أحكام البيع، وبعض أمور الربا، قد يُعذر وتلتبس عليه الأمور. لكن أصل الدين كونه يقول: أنَّ الحج غير مشروعٍ، أو الصيام غير واجبٍ، أو الزكاة غير واجبةٍ، أو الصلاة غير واجبةٍ، هذا لا يخفى على المسلمين، هذا شيء معلوم من الدِّين بالضَّرورة. س: لو قال: لا بدَّ أن تتوفر شروط فيمَن أُريد تكفيره بعينه وتنتفي الموانع؟ ج: مثل هذه الأمور الظَّاهرة ما يُحتاج فيها شيء، يَكْفُر بمجرد ظهورها؛ لأنَّ وجودها لا يخفى على المسلمين، معلوم بالضَّرورة من الدين، بخلاف الذي قد يخفى مثل: شرط من شروط الصلاة، بعض الأموال التي تجب فيها الزكاة: تجب أو لا تجب؟ بعض شؤون الحج، بعض شؤون الصيام، بعض شؤون المعاملات، بعض مسائل الربا.[1]","link":"https://binbaz.org.sa/fatwas/31453/هل-يعذر-بالجهل-من-نشا-على-عقيدة-منحرفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 035.mp3","categories":["ضوابط التكفير"]},{"id":5530,"question":"جملة من المعاصرين ذكروا أنَّ الكافر -مَن قال الكفر أو عمل بالكفر- لا يكفُر حتى تُقام عليه الحجَّة، وأدرجوا عُبَّاد القبور في هذا؟","title":"ما ضابط قيام الحجَّة على الجاهل والمبتدع؟","answer":"الجواب: هذا من جهلهم، عُبَّاد القبور كفار، واليهود كفار، والنصارى كفار، ولكن عند القتل يُستتابون، فإن تابوا وإلا قُتلوا. س: مسألة قيام الحجَّة؟ ج: بلغهم القرآن: هَذَا بَلَاغٌ لِلنَّاسِ [إبراهيم:52]، القرآن بلغهم، وبين المسلمين: وَأُوحِيَ إِلَيَّ هَذَا الْقُرْآنُ لِأُنْذِرَكُمْ بِهِ وَمَنْ بَلَغَ [الأنعام:19]، هَذَا بَلَاغٌ لِلنَّاسِ، يَا أَيُّهَا الرَّسُولُ بَلِّغْ [المائدة:67]، قد بلغ الرسول ﷺ، وجاء القرآن، وهم بين أيدينا يسمعونه في الإذاعات، ويسمعونه في غيرها، ولا يُبالون، ولا يلتفتون، وإذا جاء أحد يُنذرهم وينهاهم آذوه، نسأل الله العافية.[1]","link":"https://binbaz.org.sa/fatwas/31463/ما-ضابط-قيام-الحجة-على-الجاهل-والمبتدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 045.mp3","categories":["ضوابط التكفير"]},{"id":5533,"question":"الخفاء والوضوح ما يتغير باختلاف الأزمنة والأمكنة؟","title":"هل يتغير العُذر بالجهل باختلاف الأزمنة والأمكنة؟","answer":"الجواب: لا يتغير، كلما عظم الجهل زاد الخطب، كلما اشتدت غربةُ الإسلام زاد الخطبُ، لكن ما دام بين المسلمين يسمع القرآن ويسمع السنة قد بُلِّغ، قال الله تعالى: هَذَا بَلَاغٌ لِلنَّاسِ [إبراهيم:52]، القرآن بلاغ، ويقول سبحانه: وَأُوحِيَ إِلَيَّ هَذَا الْقُرْآنُ لِأُنْذِرَكُمْ بِهِ وَمَنْ بَلَغَ [الأنعام:19]، هو بلغه القرآن، ونقول له: تعالَ نفعل كذا، يُخاصمك ويُضاربك ولا يُعطيك ما يقبل الفائدة، أهل القبور الآن من الصعب التَّفاهم معهم في التوحيد إلا بشدةٍ، ما يرضون لأحدٍ أن يتفاهم معهم، يرون أنهم على حقٍّ، إلا مَن رحم الله، نسأل الله العافية. س: الكلام على التوحيد فقط، أما في المسائل المكفّرة من البدع مثل: الجهمية؟ ج: المسائل التي لا تكفِّر أمرها سهل، المقصود المسائل المكفِّرة. س: يُعمَّم الحكم على العوام أم هناك تفصيل؟ ج: عوامهم معهم، إذا كانوا مُعتقدين دينهم معهم، مثل: عوام اليهود والنصارى، فعوام اليهود والنصارى منهم، أما الشيء الذي قد يخفى مثل: عموم القُدرة، مثل: قصة الذي أمر أهله أن يحرقوه، وظنَّ أنه إذا حرق وذُري في اليوم الصَّائف أنه يفوت، وأنه يسلم، فأمر الله الأرض والبحر أن يجمع ما فيه، ثم قال: ما حملك على هذا؟ قال: خوفك يا رب، فتجاوز الله عنه.[1]","link":"https://binbaz.org.sa/fatwas/31466/هل-يتغير-العذر-بالجهل-باختلاف-الازمنة-والامكنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 048.mp3","categories":["ضوابط التكفير"]},{"id":5536,"question":"جماعة من المعاصرين يقولون إنه لا يكفُر الشخصُ إذا قال الكفر أو فعله إلا إذا قصد بقلبه؟","title":"هل يشترط القصد في تكفير مَنْ نطق بالكفر؟","answer":"الجواب: غلط، هذا يَكْفُر بالقول وباللسان وبالعمل، إلا إذا أُكره مع الطُّمأنينة، إذا أُكره بالضرب أو التهديد بالقتل من قادرٍ وقلبه مطمئن، مثلما فعل عمار وياسر وابن مسعود وبلال وغيرهم ، فوافقوهم، ولكن مع الطمأنينة بالقلب، مع كون القلب مطمئنًّا بالإيمان، مُوحِّدًا لله جلَّ وعلا، ولكن قالوا: إنَّ محمدًا ﷺ كاذب، أو قالوا: إنه ليس برسولٍ؛ ليدفعوا عنهم الضرب بالجريد وغيره.[1]","link":"https://binbaz.org.sa/fatwas/31469/هل-يشترط-القصد-في-تكفير-من-نطق-بالكفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 051.mp3","categories":["ضوابط التكفير"]},{"id":5868,"question":"ما حكم الذين يدعون غير الله من المسلمين عن جهل بحقيقة التوحيد؟","title":"حكم دعاء غير الله عن جهل بالتوحيد","answer":"الجواب: هذا حكمهم أن عملهم كفر، الذين يدعون غير الله من الأموات، ويستغيثون بالأموات عمل كفر، واختلف العلماء في ذلك: هل يكفر في نفسه، ويكون كافرًا، أو لا بدّ أن يعلم؟ على قولين: أحدهما: أنه لا بدّ أن يعلم؛ لأنه قد يكون اشتبه عليه أمره بسبب دعاة الباطل، وبسبب علماء السوء، واشتبه عليه الأمر، فلا بدّ أن يعلم، ولابدّ أن ينبه قبل أن يحكم عليه بالكفر، وهذا قول جماعة من أهل العلم. والقول الثاني: أنه لا يحتاج إلى بيان؛ لأن الأمر واضح، والقرآن كله فيه بيان الشرك، وهكذا السنة، والرسول بين ذلك، والعلماء بينوا ذلك، فلا يتوقف كفره على البيان، بل هو كافر بهذا العمل. ولكن يستتاب قبل أن يقتل إن كان هناك دولة إسلامية تحاسبه فإنها لا تقتله حتى تستتيبه، تقول له: تب إلى الله، ودع هذا الشرك، فإن تاب، وأقلع؛ فالحمد لله، وإن أصر عليه؛ قتل. وبكل حال فالأمر خطير، والقول بأنه كافر بمجرد هذه الأعمال قول قوي، لكن الأحوط ألا يقدم على ذلك حتى يبلغ حتى يوجه إلى الخير، ويعلم لعله يهتدي إذا تيسر ذلك ، لكن حكمه  في الدنيا حكم الكفار، ما دام عمل عمل الكفار؛ فحكمه حكمهم في الدنيا كالكفار، إذ لا يصلى عليه، ولا يغسل، ولا يرث منه المسلمون.","link":"https://binbaz.org.sa/fatwas/1210/حكم-دعاء-غير-الله-عن-جهل-بالتوحيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_207.mp3","categories":["ضوابط التكفير"]},{"id":6884,"question":"هل أصحاب الفترة بين عيسى، ومحمد -عليهما الصلاة والسلام- قد بلغتهم رسالة رسلهم السابقين لهم؟","title":"حكم أهل الفترة في الدنيا والآخرة","answer":"الجواب: أصحاب الفترة هم الذين لم تبلغهم الرسالات، لم يبلغهم دعوة نبي، لا عيسى، ولا غيره، يقال لهم أهل الفترة، وهكذا ما بين محمد ﷺ وما بين عيسى، وهي فترة طويلة، قيل: ستمائة عام، وقيل: أقل من ذلك .. الصواب: أنهم يمتحنون في الآخرة، ويؤمرون يوم القيامة، وينهون، فمن أجاب؛ دخل الجنة، ومن عصى؛ دخل النار. وقيل: إنهم من أهل الجنة، ولكن الصواب هو الأول، وقد جاء في الأحاديث ما يدل على ذلك: أنهم يمتحنون يوم القيامة، ويخرج لهم عنق من النار، ويؤمرون بالدخول فيها، فإن أجابوا؛ صارت عليهم بردًا، وسلامًا، وإن أبوا، وامتنعوا، وعصوا؛ أخذوا إلى النار.  فالحاصل: أنهم يمتحنون يوم القيامة، ومن جاء في الأحاديث أنه من أهل النار مما بين الرسول ﷺ وما بين عيسى، فلعله بلغهم شيء في ذلك، كما جاء في حديث رواه مسلم في الصحيح أن النبي  قال لرجل: إن أبي، وأباك في النار هذا عند أهل العلم.  لعل عبدالله بلغه شيء حتى استحق النار بذلك، وإلا فهو من أهل الفترة، لكن لما حكم عليه النبي بالنار؛ دل على أنه بلغه شيء يوجب ذلك، وإلا فهو من أهل الفترات، ولكن لا يصلى عليهم، ولا يدعى لهم، ولا يستغفر لهم؛ لأن النبي لما استأذن ربه في أن يستغفر لأمه -وهي من أهل الفترة- لم يؤذن له أن يستغفر لها، فدل على أن من مات على دين الكفرة، وعلى ظاهر الكفر، لا يستغفر له، ولا يحكم له بالإسلام، بل أمره إلى الله.","link":"https://binbaz.org.sa/fatwas/2780/حكم-اهل-الفترة-في-الدنيا-والاخرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1272.mp3","categories":["ضوابط التكفير"]},{"id":7214,"question":"هل أطفال النصارى واليهود وغيرهم، الأطفال الذين لم يبلغوا سن التمييز وماتوا، هل هم في الجنة، أم في النار؟","title":"حكم أولاد الكفار في الدنيا والآخرة","answer":"الجواب:\n\nسئل النبي ﷺ عن أولاد المشركين -هذا سؤال قديم- فقال : الله أعلم بما كانوا عاملين سئل عنهم النبي ﷺ فقال: الله أعلم بما كانوا عاملين.\n\nقال العلماء على هذا الحديث: إن معناه أنهم يرجعون إلى علم الله فيهم يوم القيامة، ويمتحنون يوم القيامة، فمن أطاع الله يوم القيامة عند الامتحان؛ دخل الجنة، ومن عصى؛ دخل النار.\n\nوهكذا أهل الفترة الذين ما بلغتهم دعوة الرسل، كانوا في أمكنة ما بلغتهم الدعوة، يمتحنون يوم القيامة، فمن أجاب إلى الأمر الذي طلب منه؛ صار إلى الجنة، ومن عصى؛ صار إلى النار.\n\nوهكذا أشباههم ممن كان وقت الدعوة مخرفًا، يعني قد هرم، أو مجنونًا، أو غير ذلك، يمتحن يوم القيامة، فمن أجاب إلى الخير والهدى؛ دخل الجنة، ومن عصى؛ دخل النار، وهذا هو الذي قرره جمع من أهل العلم، ونبه عليه العلامة ابن القيم -رحمه الله- في آخر كتابه: (طريق الهجرتين) في مبحث، في آخر كتابه، سماه \"طبقات المكلفين\" وهو بحث، طيب من أراده وجده.\n\nالمقصود من هذا هو المعتمد: أن أولاد المشركين معهم في أحكام الدنيا، حكمهم حكم الدنيا، يدفنون معهم في الدنيا، ولا يغسلون، ولا يصلى عليهم إذا ماتوا، وهم بين أهلهم الكفرة، حكمهم حكمهم في الدنيا، قال النبي ﷺ لما سئل عنهم قال: هم منهم لما قال له رجل: يا رسول الله إنا نبيت المشركين، ونصيب من ذراريهم، ونسائهم؟ فقال: هم منهم يعني: شأنهم شأنهم، يدفنون معهم، ولا يغسلون، ولا يصلى عليهم، لكن يوم القيامة يمتحنون، فمن قبل ما أمر الله به يوم القيامة؛ دخل الجنة، ومن عصى؛ دخل النار.\n\nالسؤال: طيب ومضمون الآية وَإِنْ مِنْ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٌ [فاطر: 24] أين النذير الآن للناس أهل الفترة، أو الناس الذين في أطراف أفريقيا؟\n\nالجواب: يعني الأمة قد يشذ منها أطراف، فيها بعض المحلات، ما يذهب لهم الدعوة.","link":"https://binbaz.org.sa/fatwas/3261/حكم-اولاد-الكفار-في-الدنيا-والاخرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1589.mp3","categories":["ضوابط التكفير"]},{"id":9818,"question":"يسأل السائل أيضاً ويقول: نعلم أن من كان من أهل الجاهلية أي قبل مبعث النبي ﷺ فهو من أهل الفترة، سؤالي عن أهل الفترة ما حكمهم؟ لأنني سمعت حديثاً عن رسول الله ﷺ: أنه جاءه رجل فقال: أين أبي؟ فقال: في النار، فذهب الرجل يبكي، فناداه فقال له: أبي وأبيك في النار فهل هذا الحديث صحيح أفيدونا أفادكم الله؟","title":"أهل الفترة وحكمهم","answer":"الجواب: الصحيح من أقوال العلماء أن أهل الفترة يمتحنون يوم القيامة ويؤمرون، فإن أجابوا وأطاعوا دخلوا الجنة، وإن عصوا دخلوا النار، وقد جاء في هذا عدة أحاديث: عن أبي هريرة ، وعن الأسود بن سريع التميمي وعن جماعة، كلها تدل على أنهم يمتحنون يوم القيامة ويخرج لهم عنق من النار ويؤمرون بالدخول فيه، فمن أجاب صار عليه برداً وسلاماً، ومن أبى التف عليه وأخذه وصار إلى النار نعوذ بالله من ذلك.\nفالمقصود: أنهم يمتحنون فمن أجاب وقبل ما طلب منه وامتثل دخل الجنة ومن أبى دخل النار، هذا هو أحسن ما قيل في أهل الفترة.\nوأما حديث: إن أبي وأباك في النار فهو حديث صحيح رواه مسلم في صحيحه: أن رجلاً قال: يا رسول الله! أين أبي؟ قال: في النار، فلما ولى دعاه، فقال: إن أبي وأباك في النار واحتج العلماء بهذا على أن أبا النبي ﷺ كان ممن بلغته الدعوة وقامت عليه الحجة، فلهذا قال: في النار، ولو أنه كان من أهل الفترة لما قيل له هذا، وهكذا لما أراد أن يستغفر لأمه عليه الصلاة والسلام نهي عن ذلك، نهي أن يستغفر لها ولكنه أذن له أن يزورها، ولم يؤذن له في الاستغفار لها.\nفهذا يدل على أنهما بلغتهما الدعوة، وأنهما ماتا على دين الجاهلية على دين الكفر، وهذا هو الأصل في الكفار أنهم في النار، إلا من ثبت -والله يعلم أحوالهم- أنه لم يبلغه الأمر ما بلغته دعوة الرسل فهذا هو صاحب الفترة، من كان في علم الله أنه لم تبلغه الدعوة فالله سبحانه وتعالى أحكم الحاكمين، هو الحكم العدل، فيمتحنون يوم القيامة.\nأما من بلغته الدعوة في حياته دعوة الرسل كدعوة إبراهيم وموسى وعيسى وعرف الحق ثم بقي على الشرك بالله فهذا ممن بلغته الدعوة، فيكون من أهل النار لأنه عصى واستكبر عن اتباع الحق، والله جل وعلا أعلم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7987/اهل-الفترة-وحكمهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_260/26008.mp3","categories":["ضوابط التكفير"]},{"id":10030,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول المعتصم جودة يوسف من الكويت، بعث بعدد من الأسئلة من أحدها يقول: هل كل من يفعل البدعة يسمى مبتدعا، ومتى تطلق كلمة مبتدع على الشخص؟","title":"الضابط في الحكم على الشخص بأنه مبتدع","answer":"الجواب: الأصل أن من فعل البدعة يقال له مبتدع هذا هو الأصل، من فعل البدعة يقال له: مبتدع، لكن إذا كان جاهلًا يُعلَّم ومتى تاب لا يسمى مبتدعًا، وإذا أصر يسمى مبتدعًا على حسب بدعته، كالذي يصر على الاحتفال بالمولد أو الموالد الأخرى يسمى مبتدع حتى يتوب، والذي يصر على البناء على القبور أو الصلاة عند القبور أو بناء المساجد عليها أو إراقة الطيب عليها يسمى مبتدع، وهكذا من فعل البدعة التي حرمها الله يسمى مبتدع، يقول النبي ﷺ: إياكم ومحدثات الأمور فإن كل بدعة ضلالة ويقول عليه الصلاة والسلام في الحديث الصحيح: أما بعد -يقول في خطبة الجمعة- أما بعد فإن خير الحديث كتاب الله وخير الهدي هدي محمد ﷺ وشر الأمور محدثاتها وكل بدعة ضلالة، ويقول ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد.\nفالمسلم يمتثل أمر الرسول ﷺ ويؤيد ما قاله عليه الصلاة والسلام، ويحذر من البدع ويسمي أهلها مبتدعين حتى يتوبوا إلى الله  والجاهل يعلم ومن تاب تاب الله عليه.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8197/الضابط-في-الحكم-على-الشخص-بانه-مبتدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_332/33207.mp3","categories":["ضوابط التكفير"]},{"id":10076,"question":"من القاهرة المستمع محمود أحمد عميرة بعث يسأل ويقول: هل يعذر الإنسان بجهله، مثلاً رجل زار قبور الأولياء بنية التبرك بهم مع أنه لا يعلم أن ذلك الفعل من الشرك الأكبر، مع بيان وتوضيح الأدلة من الكتاب والسنة، جزاكم الله خيراً؟","title":"حكم من زار قبور الأولياء للتبرك بها جاهلاً","answer":"الجواب: أمور العقيدة التي تتعلق بالتوحيد والشرك لا يعذر فيها بالجهل، وهو بين المسلمين ويسمع القرآن والأحاديث ويستطيع أن يسأل، لا يعذر بدعوة القبور والاستغاثة بالأموات وأشباه ذلك، بل يجب عليه أن يتعلم ويتفقه وليس له أن يتساهل في هذا الأمر، وقد سأل النبي ﷺ ربه ليستغفر لأمه وهي ماتت في الجاهلية فلم يؤذن له، قال: إن أبي وأباك في النار، لما سأله رجل عن أبيه، قال: إن أبي وأباك في النار، قال: ماتا في الجاهلية.\nقال جمع من أهل العلم: إنما ذلك لأنهما ماتا على علم بشريعة إبراهيم وشريعة إبراهيم النهي عن الشرك، فلعل أمه بلغها ذلك فلهذا نهي عن الاستغفار لها، ولعل أباه بلغه ذلك فلهذا قال: إن أبي وأباك في النار، فإذا كان أبوه ﷺ وأمه لم يعذرا وهما في حال الجاهلية فكيف بالذي بين المسلمين وعنده العلماء ويسمع القرآن ويسمع الأحاديث.\nفالحاصل أن هؤلاء الذين يعكفون على القبور ويستغيثون بالأموات غير معذورين بل يجب عليهم أن يتفقهوا في الدين وأن يسألوا أهل العلم، وأن لا يبقوا على حالهم السيئة والآيات تعمهم والأحاديث. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8242/حكم-من-زار-قبور-الاولياء-للتبرك-بها-جاهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_304/30405.mp3","categories":["ضوابط التكفير"]},{"id":10078,"question":"متى يعذر الإنسان بالجهل لو تكرمتم؟","title":"الأمور التي يعذر فيها المسلم بالجهل","answer":"الجواب: يعذر بالأشياء الخفية لا سيما في بعض الأحكام الشرعية قد تخفى على العامي حتى يتعلم، أما الذي بين المسلمين لو قال: ما أدري عن الزنا، ما يعذر وهو بين المسلمين، الزنا معروف عند المسلمين إنه حرام، فلو قال: ما عرفت أن الزنا حرام ما يعذر بهذا، أو قال: ما عرفت إن الخمر حرام وهو بين المسلمين ما يعذر، لكن في بعض المسائل التي قد تخفى في مسائل الأحكام الدقيقة قد يعذر فيها الإنسان من أجل كونه ليس من أهل العلم.\nكذلك لو قال: ما أعلم دعاء الأموات والاستغاثة بالأموات ممنوع ما يعذر بهذا لأن هذا هو أصل التوحيد وأصل الدين، والله أنزل القرآن للنهي عن هذه الأمور والقضاء عليها، وبين حال المشركين وحذر من أعمالهم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8243/الامور-التي-يعذر-فيها-المسلم-بالجهل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_304/30406.mp3","categories":["ضوابط التكفير"]},{"id":10224,"question":"رسالة من أحد الإخوة المستمعين، يقول: من أخوكم في الله الطويل إدريس إبراهيم، أخونا له جمع من الأسئلة، من بينها سؤال يقول: أرجو منكم التعليق على ما يقع فيه الكثير من الناس من عابدي القبور والأضرحة، من صرف العمل لها، وسؤال أصحابها شفاء المرضى، وتفريج الكرب، فهل من مات وحالته هذه يكون خالداً في جهنم؟ وهل يعذر جاهل بهذه القضية؟","title":"الحكم على عباد القبور والأضرحة، وهل لهم عذر بالجهل؟","answer":"الجواب: هذا سؤال عظيم هو جدير بالعناية، لأنه واقع في كثير من البلدان الإسلامية، وهو سؤال الأموات، والاستغاثة بالأموات، وطلبهم شفاء المرضى، أو النصر على الأعداء، وهذا من الشرك الأكبر، وهذا دين الجاهلية، دين أبي جهل وأشباهه من عباد القبور، وعباد الأصنام، يقولون: مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:3] كما حكى الله عنهم ، قال الله جل وعلا: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18] وقال سبحانه في سورة الزمر: مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:3].\nفالحاصل أن هذا العمل من الشرك الأكبر، وصاحبه إذا مات عليه يكون من أهل النار، مخلداً فيها نسأل الله العافية، إلا إذا كان لم تبلغه الدعوة، كان من أهل الفترات الذين ما بلغتهم الدعوة في محلات ما بلغتهم الدعوة، ما بلغهم القرآن، ولا كلام الرسول ﷺ، فهذا حكمه إلى الله جل وعلا يوم القيامة يمتحن يوم القيامة، فمن أجاب جواباً صحيحاً دخل الجنة، ومن أجاب جواباً غير صحيح دخل النار.\nفالمقصود أنه يمتحن يوم القيامة، فمن أجاب ما طلب منه دخل الجنة، ومن عصى دخل النار، أما من كان في الدنيا قد بلغه القرآن، وبلغته السنة، ويعيش بين المسلمين، فهذا لا يعذر بدعواه الجهل، هو قد أسرف على نفسه وتساهل ولم يسأل أهل العلم، ولم يتبصر في دينه، فهو مؤاخذ بأعماله السيئة الشركية، نسأل الله السلامة. نعم.\nالمقدم: جزاكم الله خيراً، إذاً عملية العذر بالجهل هذه.\nالشيخ: لا، العقائد التي هي أصل الإسلام، ما فيها عذر بالجهل، الله جل وعلا قال عن الكفار: إِنَّهُمُ اتَّخَذُوا الشَّيَاطِينَ أَوْلِيَاءَ مِنْ دُونِ اللَّهِ وَيَحْسَبُونَ أَنَّهُمْ مُهْتَدُونَ [الأعراف:30] ما عذرهم بحسبانهم أنهم مهتدون، ما عذرهم بجهلهم، وقال في النصارى: قُلْ هَلْ نُنَبِّئُكُمْ بِالأَخْسَرِينَ أَعْمَالًا ۝ الَّذِينَ ضَلَّ سَعْيُهُمْ فِي الْحَيَاةِ الدُّنْيَا وَهُمْ يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعًا [الكهف:103-104].\nفالحاصل أنهم بهذا كفروا، قال بعد هذا سبحانه: أُولَئِكَ الَّذِينَ كَفَرُوا بِآيَاتِ رَبِّهِمْ وَلِقَائِهِ فَحَبِطَتْ أَعْمَالُهُمْ فَلا نُقِيمُ لَهُمْ يَوْمَ الْقِيَامَةِ وَزْنًا ۝ ذَلِكَ جَزَاؤُهُمْ جَهَنَّمُ بِمَا كَفَرُوا وَاتَّخَذُوا آيَاتِي وَرُسُلِي هُزُوًا [الكهف:106] ما عذرهم بالجهل، لتساهلهم وعدم عنايتهم بطلب الحق، قال سبحانه: وَأُوحِيَ إِلَيَّ هَذَا الْقُرْآنُ لِأُنذِرَكُمْ بِهِ وَمَنْ بَلَغَ [الأنعام:19] وقال عليه الصلاة والسلام: والذي نفسي بيده، لا يسمع بي أحد من هذه الأمة يهودي ولا نصراني، ثم يموت ولم يؤمن بالذي أرسلت به، إلا كان من أصحاب النار رواه مسلم في صحيحه، ولم يقل: وفهم عني، أو تبصر، أو علم، بل علق بالسماع: والذي نفسي بيده، لا يسمع بي أحد من هذه الأمة يهودي ولا نصراني، ثم يموت ولم يؤمن بالذي أرسلت به، إلا كان من أهل النار نسأل الله العافية. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8405/الحكم-على-عباد-القبور-والاضرحة-وهل-لهم-عذر-بالجهل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31014.mp3","categories":["ضوابط التكفير"]},{"id":10242,"question":"المستمع عوض فرح بعث يسأل ويقول: هل يعذر الشخص بالجهل إذا فعل فعلًا مكفرًا وهو كبيرة من الكبائر بل من أكبرها، وجهونا حول هذا الموضوع، وكيف نقارن بين هذا وبين قوله تعالى: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]؟","title":"حكم من مات على كبيرة وهو جاهل بذلك","answer":"الجواب: لا يعذر في اقتراف المعاصي وهو بين المسلمين، في إمكانه أن يسأل أهل العلم ويتبصر، لا يعذر بالتساهل، وعليه أن يتوب إلى الله من ذلك ويبادر بالتوبة من المعصية، والمعصية تختلف إن كانت كفر كدعاء الأموات والاستغاثة بالأموات أو سب الدين أو ترك الصلاة هذه عليه التوبة إلى الله جل وعلا والمبادرة بالتوبة والله يتوب على التائبين، أما إن كانت المعصية ليست كفر مثل التدخين وشرب المسكر أكل الربا هذه معاصي، فالواجب عليه البدار بالتوبة، والاستغفار والندم والإقلاع، والعزم أن لا يعود في ذلك، وإن مات عليها فهو تحت المشيئة، مثلما قال : إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]، إذا مات على المعصية، مات وهو يأكل الربا، أو مات وهو يشرب الخمر لكنه مسلم يصلي ومسلم فهذا تحت مشيئة الله، أو مات وهو عاق لوالديه، أو مات وهو قد زنى أو ما أشبه ذلك تحت مشيئة الله، إن شاء الله سبحانه غفر له، وإن شاء عذبه على قدر المعصية التي مات عليها، إذا كان غير تائب، ما تاب، أما إذا كان تاب فالتوبة تجب ما قبلها والحمد لله، لأن التائب لا ذنب له، أما لو مات على الزنا ما تاب أو على العقوق لوالديه ما تاب، أو على شرب المسكر ما تاب أو نحو ذلك فهذا تحت مشيئة الله، إن شاء الله جل وعلا غفر له فضلاً منه وإحساناً منه جل وعلا، وإن شاء عذبه على قدر المعصية التي مات عليها، وبعد التعذيب والتطهير يخرجه الله من النار إلى الجنة إذا كان مات مسلم موحد، لا يخلد في النار إلا الكفار، لكن هذا الذي دخل النار بمعصيته إذا عذب التعذيب الذي أراده الله يخرجه الله من النار إلى الجنة بتوحيده وإيمانه الذي مات عليه، لا يخلد في النار إلا الكفرة نسأل الله العافية.\nالمقدم: اللهم آمين، جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8412/حكم-من-مات-على-كبيرة-وهو-جاهل-بذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_278/27814.mp3","categories":["ضوابط التكفير"]},{"id":10486,"question":"تردد كثيرًا سماحة الشيخ السؤال عن العذر بالجهل، فهذا مستمع يسأل ويقول: سمعت أن الذي يسب الدين كافر، فهل يتساوى في ذلك الذي يعرف أن سب الدين يخرج من الملة مع الذي لا يعرف أنه يخرج من الملة، وفي أمور الدين يعذر الإنسان بجهله، وأي الأمور التي لا يعذر فيها الإنسان بجهله، أرجو من الله ثم منكم أن تشرحوا هذه القضية شرحاً وافياً؛ لأن أناساً يشيعون ويقولون: إن العذر بالجهل وارد فيدعون الجهل؟","title":"حكم العذر بالجهل فيما هو معلوم من الدين بالضرورة","answer":"الجواب: من كان بين المسلمين لا يعذر بالجهل في مثل هذا، سب الدين ردة عن الإسلام، ترك الصلاة ردة عن الإسلام، وجحد وجوبها ردة عن الإسلام، هكذا سب الله، سب الرسول، الاستهزاء بالله، أو الاستهزاء بالرسول كل هذه ردة، ما يعذر فيها بالجهل دعوى الجهل وهو بين المسلمين؛ لأن هذا معروف بين المسلمين ومضطر، ضرورة معرفة هذا بين المسلمين، لا يخفى على أحد، ولو قال: إن الزنا حلال أو الخمر حلال كذلك ردة عن الإسلام؛ لأن هذا الشيء لا يخفى، أما إنسان في جاهلية ما يعرف الإسلام ولا هو عند المسلمين، فهذا حكمه حكم أهل الفترة، إذا مات على ذلك فأمره إلى الله يمتحن يوم القيامة، لكن بين المسلمين من سب الدين أو استهزأ بالله أو بالرسول أو ترك الصلاة، أو جحد وجوب الصلاة أو جحد وجوب الزكاة، أو جحد وجوب صوم رمضان أو جحد وجوب الحج مع الاستطاعة، أو قال: إن الزنا حلال أو الخمر حلال، أو العقوق للوالدين حلال كل هذا ردة ما يعذر فيه بالجهل؛ لأن هذه أمور ظاهرة من الدين، معلوم من الدين بالضرورة، يعرفها الخاص والعام بين المسلمين. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8661/حكم-العذر-بالجهل-فيما-هو-معلوم-من-الدين-بالضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28113.mp3","categories":["ضوابط التكفير"]},{"id":13420,"question":"سماحة الشيخ! نبدأ هذا اللقاء بسؤال من الأخ السائل باسم الأمين، الحقيقة له سؤال في العقيدة يحتاج منا إلى التفصيل -جزاكم الله خيرًا- يقول في هذا  سماحة الشيخ! في بلادنا ضل الكثير بسبب الطرق الصوفية حيث يعبدون القبور، ويدعون غير الله، ومنهم حفظة لكتاب الله، وأئمة للمساجد، سؤالي يتكون من فقرات سماحة الشيخ: هل هؤلاء كفار بسبب ارتكابهم للشرك، وبعدم معرفتهم للتوحيد إذا كانوا يجهلون معنى لا إله إلا الله، وهل يعذرون بالجهل، أم هم كفار؟ وجهونا في ضوء هذا السؤال، وبقي لي فقرات، تفضل سماحة الشيخ.","title":"حكم عباد القبور وهل يعذرون بالجهل؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فقد دل الكتاب العزيز والسنة المطهرة على بيان توحيد الله -جل وعلا- وعلى أنواع الشرك الأكبر، فمن تلبس بالشرك من سائر الناس وهو بين المسلمين ممن بلغه القرآن والسنة؛ فإنه يحكم عليه بالشرك، قال الله -جل وعلا-: وَأُوحِيَ إِلَيَّ هَذَا الْقُرْآنُ لِأُنذِرَكُمْ بِهِ وَمَنْ بَلَغَ [الأنعام:19] وقال الله -جل وعلا-: يَا أَيُّهَا الرَّسُولُ بَلِّغْ مَا أُنزِلَ إِلَيْكَ مِنْ رَبِّكَ [المائدة:67] وقال -جل وعلا-: فَإِنَّمَا عَلَيْكَ الْبَلاغُ وَعَلَيْنَا الْحِسَابُ [الرعد:40]. فمن بلغه القرآن العظيم، والسنة المطهرة، ثم تعاطى الشرك؛ يحكم عليه بالشرك؛ لتساهله، وعدم عنايته بما أوجب الله عليه من التفقه في الدين، والبصيرة، فإذا كان يدعو الأموات، ويستغيث بالأموات، أو بالنجوم، أو بالأشجار والأحجار، أو بالأصنام، أو بالجن، يدعوهم، يستغيث بهم، ينذر لهم، فهذا شرك أكبر، يستتاب من ذلك، يستتيبه ولي الأمر، فإن تاب وإلا وجب قتله على شركه بالله، كما قال النبي ﷺ: من بدل دينه فاقتلوه. والله بعث نبيه ﷺ بالدعوة إلى الله، وجهاد المشركين، فإذا كان الرجل بين المسلمين، وفي بلاد المسلمين، أو بين قوم بلغهم القرآن والسنة، ثم تساهل، واستمر على ما هو عليه؛ فإنه يحكم عليه بالشرك. فإذا كان يدعو الأموات، أو يستغيث بالأموات، ينذر لهم، أو بالجن، أو بالملائكة، أو بالأنبياء، يقول: يا سيدي فلان، أو يا نبي الله فلان اغفر لي، أو انجني من النار، أو أغثني، أو اشف مريضي، أو رد غائبي، أو أنا في جوارك، أنا في حسبك، يقول هذا للميت، أو للجن، أو للملائكة، أو لغيرهم؛ هذا من الشرك الأكبر؛ لأن الله يقول سبحانه: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] ويقول سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] ويقول -جل وعلا-: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلا يُنَبِّئُكَ مِثْلُ خَبِيرٍ [فاطر:13-14].  ويقول عن المشركين وهم جهال: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ قُلْ أَتُنَبِّئُونَ اللَّهَ بِمَا لا يَعْلَمُ فِي السَّمَوَاتِ وَلا فِي الأَرْضِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ [يونس:18] ويقول -جل وعلا- عنهم: وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ [الزمر:3] يعني: يقولون. مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:3] قال سبحانه: إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ [الزمر:3] فسماهم كذبة؛ لزعمهم أن أصنامهم تقربهم إلى الله زلفى، وسماهم كفرة بعبادتهم إياها، وشركهم إياه. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ الفقرة الثانية في رسالة هذا السائل يقول: سماحة الشيخ! هل يعذر هؤلاء -أي: يعذر عباد القبور- بالجهل، رغم وجود دعاة التوحيد بينهم؟ الشيخ: تقدم أنهم لا يعذرون، لا يعذرون، بل يجب عليهم أن يطلبوا العلم، وأن يتبصروا ويتفقهوا في الدين، ويسألوا عما أشكل عليهم، هذا الواجب عليهم، فإذا سكتوا، واستمروا على عبادة الأموات، أو الأشجار، أو الأحجار، أو الأنبياء، أو الملائكة، أو الجن؛ صاروا كفارًا بذلك في دعائهم إياهم، وطلبهم منهم الشفاعة، أو شفاء المريض، أو رد الغائب، أو ما أشبه ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11713/حكم-عباد-القبور-وهل-يعذرون-بالجهل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52701.mp3","categories":["ضوابط التكفير"]},{"id":13682,"question":"ننتقل بعد ذلك إلى رسالة بعث بها السائل رضا متولي مصري ومقيم بالرياض، يقول: سمعنا بأن والد ووالدة الرسول ﷺ ماتوا وهم على ملة قريش، وذكر: \"بأن الرسول ﷺ استأذن الله ليستغفر لهم، فلم يأذن له، فبكى وأبكى من حوله\" وجهونا في ضوء هذا السؤال؟","title":"مصير والدي النبي ﷺ في الآخرة","answer":"الجواب: نعم، النبي ﷺ استأذن أن يستغفر لعمه أبي طالب، فلم يأذن له، واستأذن أن يستغفر لأمه؛ فلم يؤذن له، وقال لما سئل عن رجل مات في الجاهلية قال: إنه في النار فلما رأى ما في وجه الرجل قال: إن أبي وأباك في النار وهذا محمول عند أهل العلم على أنهم بلغتهم الدعوة، بلغتهم دعوة إبراهيم، فالذين ماتوا في الجاهلية، وقد بلغتهم دعوة إبراهيم، قد قامت عليهم الحجة إذا ماتوا على الكفر بالله، فهم من أهل النار، أما الذين ما بلغتهم الدعوة، ولا عرفوا شيئًا؛ فهذا أمرهم إلى الله، يعتبرون من أهل الفترة، وأمرهم إلى الله، يمتحنون يوم القيامة، فمن نجح؛ دخل الجنة، ومن عصى؛ دخل النار، أما من بلغته الدعوة في حياته -دعوة إبراهيم- قبل بعث النبي ﷺ فهذا قد قامت عليه الحجة. وعلى هذا يحمل ما جرى في حق أمه وأبيه كونه استأذن أن يستغفر لأمه؛ فلم يؤذن له، وقال في أبيه: إن أبي وأباك في النار محمول على أنهم بلغتهم الدعوة. وأما أبو طالب فقد بلغته الدعوة، ودعاه ابن أخيه محمد -عليه الصلاة والسلام- واجتهد، ودعاه في مرضه؛ فأبى، وأصر على الكفر -نعوذ بالله من ذلك- فقال النبي ﷺ عند ذلك: لأستغفرن لك ما لم أنه عنك فأنزل الله في ذلك قوله -جل وعلا-: مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُوْلِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ [التوبة:113] فدل على أن من مات على الكفر بالله؛ فإنه من أصحاب الجحيم، نعوذ بالله. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12032/مصير-والدي-النبي-ﷺ-في-الاخرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51911.mp3","categories":["ضوابط التكفير"]},{"id":14073,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من ليبيا، باعث الرسالة مستمع من هناك هو (منذر . أ. أ)، أخونا منذر يقول: سمعت مؤخرًا أن من لم يكفر الكافر أو يشك في كفره؛ فهو كافر، كما أن من يشك في كفر تارك الصلاة أو المستهزي بحد من حدود الله؛ فهو كافر، فهل هذا صحيح؟","title":"حكم من لم يكفر الكافر أو شك في كفره","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد دلت الأدلة الشرعية من الكتاب والسنة على وجوب البراءة من المشركين، واعتقاد كفرهم، متى علم المؤمن ذلك، واتضح له كفرهم وضلالهم، كما قال الله  في كتابه العظيم: وَإِذْ قَالَ إِبْرَاهِيمُ لِأَبِيهِ وَقَوْمِهِ إِنَّنِي بَرَاءٌ مِمَّا تَعْبُدُونَ ۝ إِلَّا الَّذِي فَطَرَنِي فَإِنَّهُ سَيَهْدِينِ ۝ وَجَعَلَهَا كَلِمَةً بَاقِيَةً فِي عَقِبِهِ لَعَلَّهُمْ يَرْجِعُونَ [الزخرف:26-28]، أي: لعلهم يرجعون إليها في تكفير المشركين والبراءة منهم، والإيمان بأن الله هو المعبود بالحق ، وقال : قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِي إِبْرَاهِيمَ وَالَّذِينَ مَعَهُ إِذْ قَالُوا لِقَوْمِهِمْ إِنَّا بُرَآءُ مِنْكُمْ وَمِمَّا تَعْبُدُونَ مِنْ دُونِ اللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ الْعَدَاوَةُ وَالْبَغْضَاءُ أَبَدًا حَتَّى تُؤْمِنُوا بِاللَّهِ وَحْدَهُ [الممتحنة:4]، فهذا هو دين إبراهيم وملة إبراهيم والأنبياء جميعًا، البراءة من عابد غير الله، واعتقاد كفرهم وضلالهم، حتى يؤمنوا بالله وحده .\nفالواجب على المسلم أن يتبرأ من عابد غير الله، وأن يعتقد كفرهم وضلالهم، حتى يؤمنوا بالله وحده  كما حكى الله عن إبراهيم والأنبياء جميعًا، وهكذا قوله : فَمَنْ يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِنْ بِاللَّهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَى لا انفِصَامَ لَهَا وَاللَّهُ سَمِيعٌ عَلِيمٌ [البقرة:256]، والكفر بالطاغوت: معناه البراءة من عبادة غير الله واعتقاد بطلانها، وأن الواجب على كل مكلف أن يعبد الله وحده، وأن يؤمن به، ويعتقد أنه سبحانه هو المستحق للعبادة، وأن ما عبده الناس من دون الله من أصنام أو أشجار أو أحجار أو أموات أو جن أو ملائكة أو كواكب أو غير ذلك؛ أنه معبود بالباطل، قال تعالى: ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62]، الآية من سورة الحج.\nفالمؤمن إذا علم أن فلانًا يعبد غير الله؛ وجب عليه البراءة منه، واعتقاد بطلان ما هو عليه، وتكفيره بذلك إذا كان ممن بلغته الحجة، ممن كان بين المسلمين، أو علم أنه بلغته الحجة، كما قال الله : وَأُوحِيَ إِلَيَّ هَذَا الْقُرْآنُ لِأُنذِرَكُمْ بِهِ وَمَنْ بَلَغَ [الأنعام:19]، وقال تعالى: هَذَا بَلاغٌ لِلنَّاسِ وَلِيُنذَرُوا بِهِ [إبراهيم:52]، فالله أوحى القرآن إلى نبيه ﷺ، وجعله بلاغًا للناس، فمن بلغه القرآن أو السنة، ولم يرجع عن كفره وضلاله؛ وجب اعتقاد بطلان ما هو عليه وكفره.\nومن هذا: الحديث الصحيح يقول عليه الصلاة والسلام: والذي نفسي بيده لا يسمع بي أحد من هذه الأمة: يهودي ولا نصراني، ثم يموت ولم يؤمن بالذي أرسلت به؛ إلا كان من أهل النار، فبين عليه الصلاة والسلام أنه متى بلغه ما بعث به النبي ﷺ، ثم مات ولم يؤمن بذلك؛ صار من أهل النار، يعني: صار كافرًا من أهل النار؛ لكونه لم يستجب لما بلغه عن الله وعن رسوله.\nوهذا هو معنى قوله سبحانه: وَأُوحِيَ إِلَيَّ هَذَا الْقُرْآنُ لِأُنذِرَكُمْ بِهِ وَمَنْ بَلَغَ [الأنعام:19]، وقوله سبحانه: هَذَا بَلاغٌ لِلنَّاسِ وَلِيُنذَرُوا بِهِ [إبراهيم:52].\nوفي الصحيح -صحيح مسلم - عن طارق بن أشيم ، عن النبي عليه الصلاة والسلام أنه قال: من قال: لا إله إلا الله، وكفر بما يعبد من دون الله؛ حرم ماله ودمه، وفي لفظ آخر: من وحد الله، وكفر بما يعبد من دون الله؛ حرم ماله ودمه، فجعل تحريم الدم والمال مربوطًا بقوله: لا إله إلا الله، وبتوحيده الله، وكفره بالطاغوت، فلا يحرم ماله ودمه حتى يوحد الله، وحتى يكفر بالطاغوت، يعني: حتى يكفر بعبادة غير الله، الطاغوت: كل ما عبد من دون الله، يعني: حتى يكفر بعبادة غير الله، ويتبرأ منها، ويعتقد بطلانها.\nوهو معنى الآية الكريمة السابقة: فَمَنْ يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِنْ بِاللَّهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَى لا انفِصَامَ لَهَا وَاللَّهُ سَمِيعٌ عَلِيمٌ [البقرة:256]، والذي يعلم الكافر وما هو عليه من الباطل، ثم لا يكفره، أو يشك في كفره؛ معناه: أنه مكذب لله ورسوله، غير مؤمن بما حكم الله عليه من الكفر، فـاليهود و النصارى كفار بنص القرآن ونص السنة.\nفالواجب على المكلفين -من المسلمين- اعتقاد كفرهم وضلالهم، ومن لم يكفرهم، أو شك في كفرهم؛ يكون مثلهم؛ لأنه مكذب لله ورسوله، شاك بما أخبر الله به ورسوله.\nوهكذا من شك في الآخرة، شك ما يدري: هو هنا جنة وإلا ما هنا جنة؟ هنا نار وإلا ما هنا نار، هنا بعث وإلا ... ، يعني: عنده شك: هل هناك بعث ونشور؟ هل يبعث الله الموتى؟ هل هناك جنة؟ هل هناك نار؟ ما عنده إيمان يقين، عنده شك؛ هذا يكون كافرًا، حتى يؤمن بالبعث والنشور، وبالجنة والنار، وأن الله أعد الجنة للمتقين المؤمنين، وأعد النار للكافرين، لا بد من الإيمان بهذا، بإجماع المسلمين.\nوهكذا من شك في أن الله يستحق العبادة؛ يكون كافرًا بالله ، فإن الله سبحانه يقول: ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62]، ويقول سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23].. إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] .. وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5]، والآيات في هذا كثيرة.\nوهكذا من شك في الرسول ﷺ، وقال: لا أعلم أن محمدًا رسول الله، أو ما هو برسول الله، ما ... عندي شك؛ يكون حكمه حكم من أنكر رسالته، أو كذب به؛ يكون كافرًا حتى يؤمن يقينًا أن محمدًا رسول الله، وهكذا المرسلون الذين بينهم الله: كـنوح وهود وصالح وموسى وعيسى وإبراهيم ونحوهم، من شك في رسالتهم أو كذبهم؛ يكون كافرًا، نسأل الله العافية.\nوهكذا من استهزأ بالدين، من سب الدين أو استهزأ بالدين؛ يكون كافرًا، كما قال تعالى: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ ۝ لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65-66]، والذي يسب الدين ويسب الرسول، مثل المستهزئ أو أقبح وأكفر.\nأما من ترك الصلاة ولم يجحد وجوبها، فهذا فيه خلاف بين العلماء: منهم من يرى تكفيره -وهو الصواب-؛ لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة؛ فمن تركها فقد كفر، وقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة. وقال آخرون من أهل العلم: إنه لا يكفر بذلك، إذا كان لا يجحد وجوبها، بل يكون عاصيًا، ويكون كافرًا كفرًا دون كفر، وشركًا دون شرك، لكن لا يكون كافرًا كفرًا أكبر، هذا قاله جمع من أهل العلم، ومن شك في كفر هذا ما يكون كافرًا؛ لأجل الخلاف الذي فيه، من شك في كفر تارك الصلاة ولم يجحد وجوبها؛ ما يكون كافرًا، بل هذا محل اجتهاد، محل اجتهاد بين أهل العلم، فمن عرف بالأدلة الشرعية أنه كافر؛ وجب عليه تكفيره، ومن شك في ذلك ولم تظهر له الأدلة، ورأى أنه لا يكفر كفرًا أكبر بل كفر أصغر؛ هذا معذور في اجتهاده، ولا يكون كافرًا بذلك، أما من جحد وجوبها، وقال: الصلاة غير واجبة؛ فهذا كافر عند الجميع؛ ومن شك في كفره فهو كافر، نعوذ بالله.\nوهكذا من قال: إن الزكاة لا تجب وجحد وجوبها، أو صيام رمضان جحد وجوبه، أو قال: إن الحج مع الاستطاعة لا يجب؛ فهذا يكفر بذلك؛ لأنه مكذب لله ولرسوله عليه الصلاة والسلام، ومكذب لإجماع المسلمين؛ فيكون كافرًا، ومن شك في كفره فهو كافر، بعدما يبين له الدليل ويوضح له الأمر يكون كافرًا بذلك؛ لكونه كذب الله ورسوله، وكذب إجماع المسلمين.\nوهذه أمور عظيمة يجب على طالب العلم التثبت فيها، وعدم العجلة فيها؛ حتى يكون على بينة وعلى بصيرة، وهكذا العامة: يجب عليهم أن يتثبتوا، وأن لا يقدموا على شيء حتى يسألوا أهل العلم وحتى يتبصروا؛ لأن هذه مسائل عظيمة، مسائل تكفير ليست مسائل خفيفة، بل مسائل عظيمة.\nفالواجب على أهل العلم وعلى طلبة العلم أن يوضحوها للناس بالأدلة الشرعية، والواجب على من أشكل عليه شيء أن لا يعجل، وأن ينظر في الأدلة، وأن يسأل أهل العلم؛ حتى يكون على بصيرة وعلى بينة في ذلك، رزق الله الجميع التوفيق والهداية والعلم النافع والعمل الصالح.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12501/حكم-من-لم-يكفر-الكافر-او-شك-في-كفره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_609/60901.mp3","categories":["ضوابط التكفير"]},{"id":14320,"question":"من جمهورية مصر العربية رفح، السائل: (ج. س. ط) يقول: سماحة الشيخ! ما حكم الشرع في نظركم في رجل مسلم ارتكب الشرك الأكبر، فهل يعذر بجهله أم لا؟ ومتى يعذر الإنسان بالجهل وما الدليل في كلا الحالتين؟ مأجورين.","title":"حكم من ارتكب الشرك الأكبر ومتى يعذر بالجهل؟","answer":"الجواب: من ارتكب الشرك الأكبر فقد أتى أعظم الذنوب، فالواجب عليه البدار بالتوبة إلى الله سبحانه وتعالى؛ لأن الله يقول: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] ويقول سبحانه: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ [الزمر:53] يعني: بالشرك والمعاصي لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53] هذه الآية أجمع العلماء على أنها في التائبين.\nفالواجب على من فعل شيئًا من الشرك أو المعاصي أن يبادر بالتوبة وألا يقنط ولا ييئس؛ لأن الله سبحانه وعد من تاب إليه بالتوبة عليه، وهو الجواد الكريم  والرءوف الرحيم .\nوكل من كان بين المسلمين أو بلغه القرآن أو السنة فقد قامت عليه الحجة، فالواجب عليه التفقه والسؤال والتعلم حتى يبرئ ذمته، حتى يكون على بصيرة.\nأما من كان في بلاد بعيدة لم يبلغه القرآن ولا السنة فهذا يقال له: من أهل الفترة، حكمه حكم أهل الفترة، ليس بمسلم ولا كافر بل هو من أهل الفترة موقوف أمره إلى يوم القيامة، يمتحن يوم القيامة، فإن أجاب دخل الجنة، وإن عصى دخل النار؛ لأنه لم تبلغه الدعوة.\nأما من كان بين المسلمين قد سمع القرآن سمع السنة عنده العلماء ثم يعرض ولا يسأل ولا يتبصر فهذا غير معذور، نسأل الله العافية. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12782/حكم-من-ارتكب-الشرك-الاكبر-ومتى-يعذر-بالجهل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55006.mp3","categories":["ضوابط التكفير"]},{"id":16065,"question":"المستمع سعيد رمضان بعث برسالة وضمنها سؤالًا واحدًا يقول فيه: هل يوجد عذر بالجهل في توحيد الربوبية، وتوحيد الألوهية، أم لا؟ وهل العذر بالجهل مسألة قياسية تختلف حسب الزمان والمكان؟","title":"مسألة العذر بالجهل في أمور العقيدة؟","answer":"الجواب: ليس في العقيدة توحيد الربوبية والإلهية والأسماء والصفات، ليس فيها عذر، بل يجب على المؤمن أن يعتقد العقيدة الصحيحة، وأن يوحد الله -جل وعلا- ويؤمن بأنه رب العالمين، وأنه الخلاق العليم، وأنه منفرد بالربوبية، ليس هناك خالق سواه، وأنه المستحق للعبادة وحده دون كل ما سواه، وأنه ذو الأسماء الحسنى، والصفات العلى، لا شبيه له، ولا كفء له. عليه أن يؤمن بهذا، وليس له عذر في التساهل في هذا الأمر إلا إذا كان بعيدًا عن المسلمين في أرض لا يبلغه فيها الوحي، فإنه معذور في هذه الحالة، وأمره إلى الله، يكون حكمه حكم أهل الفترات، أمره إلى الله يوم القيامة، يمتحن، فإن أجاب جوابًا صحيحًا؛ دخل الجنة، وإن أجاب جوابًا فاسدًا؛ دخل النار.  المقصود: أن هذا يختلف، فإذا كان في محل بعيد لا يسمع القرآن والسنة؛ فهذا حكمه حكم أهل الفترة، وحكمهم عند أهل العلم أنهم يمتحنون يوم القيامة، فمن أجاب؛ دخل الجنة، ومن عصى؛ دخل النار. وأما كونه بين المسلمين يسمع القرآن والسنة، ثم يبقى على الشرك، وعلى إنكار الصفات؛ فهو غير معذور، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم. المقدم: يسأل في آخر سؤاله سماحة الشيخ ويقول: هل العذر بالجهل مسألة قياسية تختلف من زمان إلى زمان، ومكان إلى آخر؟ الشيخ: لا تختلف، لا، الجهل ليس بعذر بالنسبة للعقيدة إلا إذا كان في محل لم تبلغه الدعوة، لا القرآن، ولا السنة. أما في الأحكام فهو عذر بأن جهل الحكم الشرعي في بعض الأحكام التي قد تخفى، أو في دقائق الصفات، بعض الصفات التي قد تخفى فهذا عذر، أما في الأمور الواضحة، الأمور التي تعلم بالضرورة كالإيمان بتوحيد الله، وأنه الخلاق العليم، وأنه مستحق العبادة، وأنه الكامل في أسمائه وصفاته، والإيمان بما جاء في القرآن العظيم، والسنة المطهرة من أسماء الله، وصفاته، هذا ليس محل العذر إذا كان ممن بلغه القرآن والسنة، نسأل الله السلامة. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14696/مسالة-العذر-بالجهل-في-امور-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74821.mp3","categories":["ضوابط التكفير"]},{"id":16104,"question":"هذا سائل للبرنامج -الحقيقة- أرسل بهذه الرسالة يقول: سماحة الشيخ! أرجو التفضل بالإجابة على سؤالي -(س. ف) مصري، ويعمل بالأردن- يقول: هل هناك عذر بالجهل في العقيدة (لا إله إلا الله) وإن لم يكن هناك عذر بالجهل، فما حكم الشرع -في نظركم سماحة الشيخ- فيمن لم يصلِ إلا بعض الصلوات؟ وهل نأكل من ذبيحته؟ وهل إذا وقف إمام وهو يعتقد في أهل القبور، ويقول: بأنهم أناس صالحون، وأن الذهاب إليهم ليس شركًا؛ هل يحكم للمرء بالإسلام بمجرد النطق بالشهادتين، أفتونا في ذلك مأجورين؟","title":"مسألة العذر بالجهل في مسائل العقيدة","answer":"الجواب: لا عذر بالجهل في هذه المسائل، في مسائل العقيدة، ومسائل التوحيد، والشرك فيمن كان بين المسلمين، بل يجب عليه أن يتعلم، ويتفقه، ويحذر، ولا يعذر في هذا، فإذا دعا الأموات، أو استغاث بالأموات، أو نذر للأموات؛ هذا شرك أكبر، ولا يكفيه مجرد الشهادتين، وهو يتعاطى الشرك، يعبد الأموات، يستغيث بهم، ينذر لهم.. ونحو ذلك، بل هذا من الشرك الأكبر، ولا يعذر في ذلك، بل يجب عليه أن يخلص العبادة لله وحده، وأن يتجنب الشرك، ويحذره من جميع الوجوه. وترك الصلاة كفر، الذي لا يصلي كافر كما قال ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة قال ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر إنما الجهل عذر في مسائل خفية، مثل بعض الأحكام التي قد تخفى على الإنسان، أو أهل الفترة الذين ما عندهم إسلام، ما بلغهم الإسلام، ما بلغهم مجيء محمد ﷺ هؤلاء يقال لهم: أهل الفترة، يمتحنون يوم القيامة، فإن نجحوا في الامتحان؛ نجوا، وإن لم ينجحوا؛ هلكوا، يمتحنهم الله، ويأمرهم وينهاهم، وإن أطاعوه؛ دخلوا الجنة، وإن عصوه؛ دخلوا النار يوم القيامة، هؤلاء أهل الفترة الذين ما بلغهم الإسلام، ولا بلغهم القرآن، ولا بلغهم بعث النبي ﷺ. الله -جل وعلا- يقول: وَأُوحِيَ إِلَيَّ هَذَا الْقُرْآنُ لِأُنذِرَكُمْ بِهِ وَمَنْ بَلَغَ [الأنعام:19] من بلغه القرآن، وبلغه الرسول؛ وجب عليه التعلم، والتفقه، ولا يعذر بالإعراض، والجهل، والتساهل، نسأل الله العافية، ويقول الله في القرآن: هَذَا بَلاغٌ لِلنَّاسِ [إبراهيم:52] نعم. المقدم: أحسن الله إليكم -سماحة الشيخ- وبارك فيكم!","link":"https://binbaz.org.sa/fatwas/14751/مسالة-العذر-بالجهل-في-مساىل-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57923.mp3","categories":["ضوابط التكفير"]},{"id":17452,"question":"هذا السائل الذي لم يذكر الاسم في هذه الرسالة يقول: سماحة الشيخ! من هم أهل الفترة؟ وهل صحيح بأنه يوجد منهم أحد الآن؟ علمًا بأن البعض يقول: بأنهم في مناطق في العالم يعيشون بمعزل عن العالم الخارجي، مثل أدغال إفريقيا، وغابات الصين، وغير ذلك سماحة الشيخ.","title":"المقصود بأهل الفترة","answer":"الجواب: أهل الفترة: هم الذين لم تبلغهم الرسالة، هؤلاء هم أهل الفترة، لا سمعوا بالقرآن، ولا بالرسول ﷺ هؤلاء يقال لهم: أهل الفترة، أما من بلغه القرآن، أو بلغه خبر الرسول ﷺ أن الله بعثه إلى الناس يدعوهم، ولم يبال ليس من أهل الفترة، لكن من لم يبلغه ذلك يقال له: من أهل الفترة. والصواب فيهم أنهم يمتحنون يوم القيامة، يمتحنهم الله يوم القيامة، فمن أجاب دخل الجنة، ومن عصى دخل النار، نعم، نسأل الله العافية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16321/المقصود-باهل-الفترة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77209.mp3","categories":["ضوابط التكفير"]},{"id":18038,"question":"من جمهورية مصر العربية سيناء هذه الرسالة بعث بها أخ لنا من هناك يقول: المرسل (ج. م. ع) يسأل ويقول: وقع خلاف بين شخصين حول تكفير من يطوف حول القبر ويستغيث به، فمنهم من يقول: إن هذا الفعل فعل شرك ولا خلاف، ولكن يعذر صاحب هذا الفعل لجهله بأمور التوحيد، والآخر يقول: بكفر ذلك الشخص الذي يستغيث بغير الله، ولا يعذر بسبب الجهل بأمور التوحيد، ولكن يعذر في الفرعيات والأمور الفقهية.والسؤال هو: أي الرأيين صواب؟ وأيهما خطأ؟ جزاكم الله خيرًا.","title":"العذر بالجهل في مسائل الاعتقاد","answer":"الجواب: الصواب قول من قال: إن هذا لا يعذر؛ لأن هذه أمور عظيمة وهي من أصول الدين، وهي أول شيء دعا إليه النبي ﷺ قبل الصلاة والصوم والزكاة وغير ذلك، فأصول الدين لا يعذر فيها بالجهل لمن هو بين المسلمين ويسمع القرآن ويسمع الأحاديث، والاستغاثة بأصحاب القبور والنذر لهم ودعاؤهم وطلبهم الشفاء والمدد، كل هذا من أعظم الشرك بالله  والله سبحانه يقول في كتابه العظيم: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117]؛ فسماهم كفارًا بذلك، وقال : ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝  إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلا يُنَبِّئُكَ مِثْلُ خَبِيرٍ [فاطر:13-14] سبحانه وتعالى، فسمى دعاءهم إياهم شركًا. والله يقول جل وعلا: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] ويقول سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ[يونس:106]، فالظالمون هم المشركون، إذا أطلق الظلم فهو الشرك، كما قال : إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ[لقمان:13]. وهكذا الطواف بالقبور إذا طاف يتقرب بذلك إلى صاحب القبر، هو مثل إذا دعاه واستغاث به يكون شركًا أكبر. أما إذا طاف يحسب أن الطواف بالقبور قربة إلى الله، يقصد التقرب إلى الله كما يطوف الناس بالكعبة يتقرب إلى الله بذلك، وليس يقصد الميت، هذا من البدع، ومن وسائل الشرك المحرمة الخطيرة، ولكن الغالب على من طاف بالقبور أنه يتقرب إلى أهلها بالطواف، ويريد الثواب منهم، والشفاعة منهم، وهذا شرك أكبر نسأل الله العافية، كالدعاء. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17070/العذر-بالجهل-في-مساىل-الاعتقاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_600/60003.mp3","categories":["ضوابط التكفير"]},{"id":18327,"question":"هذا سائلة للبرنامج (م. هـ) مقيمة بالسعودية تقول سماحة الشيخ! أرجو توضيح هذه العبارة من كلام شيخ الإسلام ابن تيمية رحمه الله:قال رحمه الله: إن القول قد يكون كفر فيطلق القول بتكفير صاحبه، ويقال: من قال كذا فهو كافر، لكن الشخص المعين لا يحكم بكفره، حتى تقوم عليه الحجة التي يكفر تاركها، هل هذا يا سماحة الشيخ! عام في الأقوال والأفعال الاعتقادية والعملية، أفتونا في ضوء هذا السؤال؟","title":"حكم من ارتكب أمرًا جاهلًا يكفر فاعله","answer":"الجواب: نعم هذا هو الصواب، فإذا سب الله أو سب الرسول عليه الصلاة والسلام أو استهزأ بالدين كفر، لكن إذا كان في بلاد يجهل هذا، يعلم أن هذا ما يجوز وأن هذا كفر، إذا كان يظن أنه جاهل بها، ليس بين المسلمين، بل في بلاد الكفرة، بلاد غريبة عن الإسلام، يظن أنه يخفى عليه الأمر يبين له، فإذا عاد إلى هذا بعد ما يبين له أن هذا حرام وأن هذا لا يجوز يكفر، إذا سب الله أو سب الرسول ﷺ أو سب الدين، أو سب الإسلام يكون كفرًا أكبر. وهكذا لو سجد لغير الله سجد للقبور، وهو ما عنده مسلمون يرشدونه في بلاد الكفرة يعلم حتى يفهم أن هذا منكر وأنه ما يجوز، كما قال الله جل وعلا: وَمَا كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولًا [الإسراء:15]. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17382/حكم-من-ارتكب-امرا-جاهلا-يكفر-فاعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91315.mp3","categories":["ضوابط التكفير"]},{"id":18370,"question":"أريد تفسيرًا لقاعدة: كفر المعين؟","title":"متى يكفر المعين؟","answer":"الجواب: يمكن أن يقال في هذا: أن المعين يكفر إذا تعاطى أسباب الكفر؛ فإنه يكفر كفرًا معينًا، فإذا علم أنه يسب الدين أو يسب الرسول ﷺ أو يترك الصلاة عمدًا أو جحدًا لوجوبها فيقال: فلان كافر لما أظهره من الكفر، لكن عند قتله لابد أن يستتاب لعله يندم لعله يرجع، فإن تاب وإلا قتل على الصحيح الذي عليه جمهور أهل العلم فإنه يقتل؛ لقول النبي ﷺ: من بدل دينه فاقتلوه. قال بعض أهل العلم: يسجن ويعذب حتى يموت أو يتوب، والصواب عند جمهور أهل العلم أنه لا يسجن إلا ريثما يستتاب فقط، فإذا تاب فالحمد لله وإن لم يتب وجب قتله بعد الاستتابة. وذهب كثير من أهل العلم إلا أنه يستتاب ثلاثة أيام يضيق عليه ثلاثة أيام لعله ينتبه، لعله يرجع، وإن لم يمهل ثلاثة أيام بل استتيب ثم قتل في الحال إذا لم يتب فلا بأس بذلك لكن يستتاب ثلاثة أيام يكون أولى كما جاء ذلك عن عمر : كونه يستتاب ثلاثة أيام يكن له فيها فسحة لعله يتراجع، لعله يندم، لعله يتذكر ما فيه سعادته. فالحاصل أن من أتى بأعمال الكفر كفر بعينه وقيل: هذا كافر، إلا إذا كان مثله يجهل ذلك كالذين عاشوا في بلاد بعيدة عن الإسلام وجاهل.. أفريقيا وأمريكا ونحو ذلك فهؤلاء لابد أن يعلموا ويوجهوا ويبصروا حتى إذا عرفوا ذلك ثم استمروا على الكفر كفروا، وإلا فالذي بين أهل الإسلام ويسمع الآيات ويسمع الأحاديث أو في أمور ظاهرة لا تخفى على أهل الإسلام كالزنا ونحوه فهذا يكفر كفرًا معينًا إذا قال: الزنا حلال، أو الخمر حلال، أو الربا حلال، فقد كذب الله وكذب رسوله فيكون كافرًا، أو قال: الصلاة ما هي بواجبة، أو الزكاة ما هي بواجبة، أو صوم رمضان ما هو بواجب على المكلفين، هذا مكذب لله ولرسوله، والشيء المعلوم من الدين بالضرورة فيكون كافرًا نسأل الله العافية، لكن إذا استتيب قبل أن يقتل هذا هو المشروع، أن يستتاب قبل أن يقتل وأن تكون المدة ثلاثة أيام لعله يتراجع.. لعله يتوب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17449/متى-يكفر-المعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_862/nour_86205.mp3","categories":["ضوابط التكفير"]},{"id":18371,"question":"رسالة وصلت إلى البرنامج من السودان وباعثها أحد الإخوة من هناك يقول أخوكم محمد عمر إبراهيم من كسلا، أخونا يسأل ويقول: بعض العلماء يرى أنه لا يجوز تكفير أهل القبلة وكل من قال: لا إله إلا الله، لكن  هل كل من قال: لا إله إلا الله مع الاعتقادات الخاطئة من الشرك بالله بدعاء غيره وتقديم الشعائر لغيره، هل يعتبر هذا ضمن ما قالوا: ولا يجوز تكفيرهم؟ نرجو الإيضاح جزاكم الله خيرًا.","title":"منهج أهل السنة والجماعة في التكفير","answer":"الجواب: نعم، أهل السنة رحمهم الله يقولون: لا يكفر المسلم بذنب، ومرادهم الذنوب التي دون الشرك، ودون الكفر كالزنا والسرقة والعقوق للوالدين أو أحدهما وشرب المسكر، ونحو ذلك، إذا فعل المسلم شيئًا من هذا ما يكون كافرًا كفرًا أكبر، ولكن يكون عاصيًا، ويكون فاسقًا، ولا يكفر بذلك ما دام موحدًا مؤمنًا وإنما فعل هذا طاعة للهوى وليس مستحلاً لما حرم الله بالسكر والربا ونحو ذلك، فهذا يكون عاصيًا، ويكون فاسقًا، ويكون ضعيف الإيمان عند أهل السنة، ولا يكون كافرًا. لكن اختلف العلماء في ترك الصلاة كسلًا، هل يعتبر من هذا الصنف؟ أو يعتبر من أنواع الردة؟ على قولين لأهل العلم: والصواب: أنه يعتبر من نواقض الإسلام، ومن أعمال الردة، وإن لم يجحد وجوبها؛ لأنها عمود الإسلام وأعظم أركانه بعد الشهادتين، ولأنه ورد فيها من الأدلة على تعظيمها وأن تركها كفر أكبر ما لم يوجد في غيرها من فروع الإسلام. وهكذا كل عمل أو قول يتضمن تنقص الإسلام أو الطعن في الإسلام أو الاستهزاء بالإسلام أو جحد ما جاء به الإسلام وغيره من المحرم يكون ردة عن الإسلام، كما لو استهزأ بالصلاة، أو استهزأ بالصيام أو بالحج، أو بأخبار يوم القيامة ،أو بغير ذلك من أمور الدين يكون كفره أكبر، كما قال سبحانه: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ ۝ لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65-66]. وهكذا سب الدين كفر أكبر، الذي يسب الإسلام أو يسب الصلاة، أو يسب الرسول عليه الصلاة والسلام يكون كفرًا أكبر نعوذ بالله من ذلك. وهكذا من استغاث بالأموات أو بالأصنام، أو دعاهم لكشف ضر أو جلب نفع أو طلبهم المدد، المدد المدد يا سيدي فلان، أو من الأصنام، أو من الأشجار أو من الجن كل هذا يكون كفرًا أكبر؛ لأن هذا مما يناقض لا إله إلا الله، فلابد في حق من قال: لا إله إلا الله، أن لا ينقضها بأعماله ولا بأقواله، ولابد أن يعتقد ما دلت عليه من توحيد الله، وأنه مستحق العبادة  فإذا قالها ولم يعتقد معناها أو لم يعمل بمعناها صار كافرًا، كالمنافقين يقولون: لا إله إلا الله وهم في الدرك الأسفل من النار؛ لأنهم قالوها باللسان فقط. وهكذا كثير من المرتدين لما ينتسب إلى الإسلام يقول: لا إله إلا الله، ولكنه يتعاطى ضدها من القول والعمل، فلا ينفعه دعوى الإسلام ولا ينفعه قول: لا إله إلا الله مع كونه أتى بما يناقضها من الذبح لغير الله للجن أو دعاء غير الله كالأموات أو الأصنام أو ما أشبه ذلك، أو الاستغاثة بغير الله عند الشدائد أو ما أشبه هذا من أنواع العبادة التي يصرفها لغير الله، فإنه يكون بذلك مشركًا شركًا أكبر وعليه أن يبادر بالتوبة قبل أن يموت على ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17444/منهج-اهل-السنة-والجماعة-في-التكفير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_862/nour_86203.mp3","categories":["ضوابط التكفير"]},{"id":18831,"question":"هذا السائل يقول: سماحة الشيخ، العذر بالجهل عمومًا، هل له قواعد وأسس يقوم عليها؟ثم هل هو عام بمعنى في كل زمان ومكان؟ وهل يعذر الجهل في المجتمع المسلم عامة والمجتمع الذي فيه مسلم وغيره؟أيضًا سماحة الشيخ لعل لكم توجيه في هذا الموضوع، وما هي الأسس والقواعد في إقامة الحجة؟ وهل كل من بلغ آية أو حديث يعتبر قائمًا بالحجة؟","title":"ضابط العذر بالجهل في مسائل الأحكام والعقيدة","answer":"الجواب: الجهل فيه تفصيل: العذر فيما قد يخفى من مسائل الأحكام، أو مسائل العقيدة التي قد تخفى، وأما جنس الجهل في الأمور الظاهرة ما هو بعذر؛ لأن صاحبه هو المقصر المتساهل، يقول الله -جل وعلا-: وَمَا كَانَ اللَّهُ لِيُضِلَّ قَوْمًا بَعْدَ إِذْ هَدَاهُمْ حَتَّى يُبَيِّنَ لَهُمْ مَا يَتَّقُونَ[التوبة:115] ما قال: حتى يتبين لهم، قال: حتى يبين لهم، قال تعالى: وَمَا كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولًا[الإسراء:15] ما قال: حتى يفهموا كلام الرسول، قال: حتى نبعث رسولاً فعلى الرعية، وعلى الأمة؛ أن تتفهم كلام الرسول ﷺ أن تتفهم القرآن، أن تسأل عما أشكل عليها؛ لأن الرسول ﷺ مبلغ، والقرآن مبلغ هَذَا بَلاغٌ لِلنَّاسِ[إبراهيم:52] ويقول الله -جل وعلا-: يَا أَيُّهَا الرَّسُولُ بَلِّغْ مَا أُنزِلَ إِلَيْكَ مِنْ رَبِّكَ[المائدة:67] ويقول سبحانه: وَأُوحِيَ إِلَيَّ هَذَا الْقُرْآنُ لِأُنذِرَكُمْ بِهِ وَمَنْ بَلَغَ[الأنعام:19] فالأمة مبلغة بالقرآن وبالرسول. فالذي يعيش بين المسلمين والقرآن موجود، والسنة موجودة، ولا يبالي ولا يسأل؛ ما هو معذور، أما في دقائق الأمور مثل بعض الأحكام، بعض مسائل الربا، بعض مسائل العقود؛ قد تخفى عليه يعذر، إذا كان مثله لا يحسن معرفة ذلك، مثل الذي قال لأولاده: إذا مت فحرقوني، ثم ذروني في البحر؛ فلئن قدر الله ليعذبني، ظن أن هذا يفوت الله لجهله بكمال قدرة الله ، فعذره الله لما جمع ما في البر والبحر من جسمه، وقام بين يديه سأله ما حملك على هذا؟ قال: خوفك، فغفر الله له من أجل شدة خوفه من الله، وجهله بهذا الأمر الدقيق، وهكذا في مسائل كثيرة في العقود، في البيع، وفي المحرمات قد يخفى عليه بعض الأشياء التي يخفى دليلها. أما إنسان يسمع القرآن، ويسمع السنة، وعنده من يرشده، ولا يبالي، ولا يسأل الشرك أعظم الذنوب، لا يتساهل في هذا مثل مسائل أخرى عقوقه لوالديه أمر واضح، مثلما يفعل بعض الناس من ترك الصلاة لأن هذا أمر واضح ما هو معذور، لأنه شيء واضح بين المسلمين، أما الشيء الدقيق الذي قد يخفى يعذر فيه، نعم. المقدم: جزاكم الله خير سماحة الشيخ، إذًا يا سماحة الشيخ، العامة عليهم أن يسألوا عما أشكل عليهم؟ الجواب: الله يقول: فَاسْأَلُوا أَهْلَ الذِّكْرِ[النحل:43] عليهم أن يسألوا، وعامة الكفار في مكة ما عذرهم الله، الرسول ﷺ بين أيدهم، وهكذا في المدينة ما عذر المنافقين، ولا عذر اليهود؛ لأنهم يسمعون كلام الله، ويسمعون القرآن، ولم يستجيبوا. نعم، وفيهم العامة. المقدم: نعم نعم، جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17990/ضابط-العذر-بالجهل-في-مساىل-الاحكام-والعقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_792/nour_79203.mp3","categories":["ضوابط التكفير"]},{"id":19376,"question":"رسالة وصلت إلى هذا البرنامج من جمهورية مصر العربية أسيوط، باعثها أخ لنا من هناك طه بن محمد بن محمود بن عبد الباقي.أخونا طه له جمع من الأسئلة يسأل مثلًا: ما موقف السلف رحمهم الله كالإمام ابن تيمية وابن عبد الوهاب، من قضية العذر بالجهل؟ وهل هي واردة؟ وهل تطرق إليها السلف؟ أم أنها باطلة لا أصل لها في قضية التوحيد؟","title":"مسألة العذر بالجهل","answer":"الجواب: الجهل في الجملة قد يكون عذرًا، وقد لا يكون عذرًا. فإذا كان الشخص المكلف بعيدًا عن أهل الإسلام، وعن أهل العلم كالذي ينشأ في بلاد بعيدة عن المسلمين، ولم تبلغه الرسالة ولا القرآن ولا السنة هذا يكون معذورًا بالجهل، وله حكم أهل الفترات يوم القيامة يمتحنون فإن أجاب دخل الجنة، وإن عصى دخل النار. قد يكون معذورًا أيضًا في الأشياء الخفيفة في الفروع التي قد تخفى على مثله، كما عذر النبي ﷺ صاحب الجبة لما أحرم في الجبة وتضمخ بالطيب، وقد أحرم بالعمرة قال له عليه الصلاة والسلام: انزع عنك الجبة واغسل عنك الخلوق، واصنع في عمرتك ما أنت صانع في حجتك ولم يأمره بالفدية عن لبسه الجبة ولا عن تضمخه بالطيب للجهل. فالحاصل أن الجهل عذر في الأمور التي قد يخفى مثلها من المسائل الفرعية أو في حق من كان بعيدًا عن المسلمين وعن سماع القرآن والسنة، كأهل البلاد التي تبعد عن المسلمين في أطراف الدنيا، ومثل أهل الفترة الذين ما بلغتهم الرسالات فهذا يعذرون بالجهل. والصحيح أنهم يمتحنون يوم القيامة فمن أجاب الأمر دخل الجنة ومن عصى دخل النار، أما من بين المسلمين يسمع القرآن يسمع السنة هذا غير معذور لا في العقيدة ولا في غيرها، قال الله جل وعلا: وَأُوحِيَ إِلَيَّ هَذَا الْقُرْآنُ لِأُنذِرَكُمْ بِهِ وَمَنْ بَلَغَ[الأنعام:19] الله جعل القرآن نذيرًا، ومحمد جعله نذيرًا، فالقرآن نذير ومحمد نذير، فالذي يبلغه القرآن والسنة ويعيش بين المسلمين هذا غير معذور، عليه أن يسأل، وعليه أن يتفقه في الدين، وعليه أن يتعلم، والله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18597/مسالة-العذر-بالجهل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_934/nour_93406.mp3","categories":["ضوابط التكفير"]},{"id":19495,"question":"ما رأي سماحتكم في مسألة العذر بالجهل وخاصة في أمر العقيدة؟ وضحوا لنا هذا الأمر جزاكم الله خيرًا.","title":"مسألة العذر بالجهل","answer":"الجواب: العقيدة أهم الأمور، وهي أعظم واجب، وحقيقتها الإيمان بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، وبالقدر خيره وشره، والإيمان بأنه سبحانه هو المستحق للعبادة، والشهادة له بذلك، وهي شهادة: أن لا إله إلا الله، يشهد المؤمن بأنه لا معبود حق إلا هو  والشهادة بأن محمدًا رسول الله أرسله الله إلى الثقلين الجن والإنس، وهو خاتم الأنبياء؛ كل هذا لا بد منه، وهذا من صلب العقيدة، فلا بد من هذا في حق الرجال والنساء جميعًا وهو أساس الدين، وأساس الملة. كما يجب الإيمان بما أخبر الله به ورسوله من أمر القيامة، والجنة والنار، والحساب والجزاء، ونشر الصحف وأخذها باليمين أو بالشمال، وميزان وزن الأعمال إلى غير ذلك مما جاءت به الآيات القرآنية، والأحاديث النبوية. فالجهل بهذا لا يكون عذرًا، بل يجب على كونه يعلم هذا، وأن يتبصر فيه، ولا يعذر بقوله: إني جاهل بهذه الأمور، وهو بين المسلمين، وقد بلغه كتاب الله، وسنة الرسول عليه الصلاة والسلام، هذا يسمى معرضًا، يسمى غافلًا ومتجاهلًا لهذا الأمر العظيم، فلا يعذر. أما من كان بعيدًا عن المسلمين في أطراف البلاد التي ليس فيها مسلمون، ولم يبلغه القرآن، ولا السنة؛ فهذا معذور، وحكمه حكم أهل الفترة إذا مات على هذه الحالة، حكمه حكم أهل الفترات الذين يمتحنون يوم القيامة، فمن أجاب وأطاع الأمر دخل الجنة، ومن عصى دخل النار. أما المسائل التي قد تخفى في بعض الأحيان على بعض الناس كبعض أحكام الصلاة، أو بعض أحكام الزكاة، أو بعض أحكام الحج؛ هذه قد يعذر فيها بالجهل، ولا حرج في ذلك؛ لأنها تخفى على كثير من الناس، وليس كل واحد يستطيع الفقه فيها. هذه المسائل أمرها أسهل، والواجب على المؤمن أن يتعلم، وأن يتفقه في الدين، ويسأل أهل العلم كما قال الله سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ[النحل:43] ويروى عنه عليه الصلاة والسلام أنه قال لقوم أفتوا بغير علم: ألا سألوا إذ لم يعلموا، إنما شفاء العي السؤال، وقال عليه الصلاة والسلام: من يرد الله به خيرًا يفقهه في الدين. فالواجب على الرجال والنساء من المسلمين التفقه في الدين، والتبصر والسؤال عما أشكل، وعدم السكوت على الجهل، وعدم الإعراض، وعدم الغفلة؛ لأنهم خلقوا ليعبدوا الله، ويطيعوه  ولا سبيل إلى ذلك إلا بالعلم، والعلم لا يحصل هكذا من دون طلب ولا سؤال، لا بد من طلب العلم، ولا بد من السؤال لأهل العلم حتى يتعلم الجاهل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18745/مسالة-العذر-بالجهل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_945/nour_94511.mp3","categories":["ضوابط التكفير"]}]
